/* Généré depuis le guidebook de la maquette. Le contenu reste hors de la limite du champ HTML. */
(function () {
  var mount = document.getElementById("lgdc-guidebook-mount");
  if (!mount) return;
  var fragment = document.createElement("template");
  fragment.innerHTML = "<main class=\"lgdc lgdc-forum\" id=\"lgdc-forum\">\n\n<header class=\"lgdc-forum-head lgdc-mbs__head\">\n  <div>\n    <nav class=\"lgdc-micro lgdc-crumbs\" aria-label=\"Fil d’Ariane\"><a href=\"/\">Index</a></nav>\n    <h1>Guidebook</h1>\n  </div>\n</header>\n\n<div class=\"lgdc-gb\">\n  <input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-bases\" class=\"lgdc-gb__radio\" autocomplete=\"off\" checked><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-reglement\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-clans\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-code\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-noms\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-systeme\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-remedes\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-glossaire\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gb\" id=\"lgdc-gb-credits\" class=\"lgdc-gb__radio\" autocomplete=\"off\">\n  <aside class=\"lgdc-gb__side\" aria-label=\"Chapitres du guidebook\">\n    <ul class=\"lgdc-gb__chapters\"><li><label for=\"lgdc-gb-bases\">Les bases</label></li><li><label for=\"lgdc-gb-reglement\">Règlement</label></li><li><label for=\"lgdc-gb-clans\">Les Clans</label></li><li><label for=\"lgdc-gb-code\">Le code des guerriers</label></li><li><label for=\"lgdc-gb-noms\">Les noms</label></li><li><label for=\"lgdc-gb-systeme\">Le système</label></li><li><label for=\"lgdc-gb-remedes\">Les remèdes</label></li><li><label for=\"lgdc-gb-glossaire\">Glossaire</label></li><li><label for=\"lgdc-gb-credits\">Crédits</label></li></ul>\n  </aside>\n\n  <article class=\"lgdc-frame lgdc-gb__page\">\n    <div class=\"lgdc-frame__in\">\n      <div class=\"lgdc-gb__panel\" data-tab=\"bases\">\n        <section id=\"foret\">\n          <h2>La forêt</h2>\n          <p>Wildheart se déroule en 2026, dans la réserve intégrale d’Arc-Châteauvillain, au cœur du Parc national de forêts, entre la Champagne et la Bourgogne. Sur un peu plus de 3 000 hectares, on ne coupe plus d’arbres et la forêt évolue seule. Les humains y sont rares : on n’y entre que sur autorisation, à part sur un sentier.</p>\n          <p>Quatre Clans de chats sauvages s’y partagent le territoire. Chacun a ses frontières, ses lieux et ses règles, et aucun ne vit en paix très longtemps avec ses voisins.</p>\n          <p>Le Clan du Crépuscule vit sur les affleurements calcaires et les éboulis du rebord du plateau. Le Clan du Hêtre tient la futaie de hêtres, au centre de la réserve. Le Clan de l’Orchidée occupe les clairières et les pelouses de la lisière, contre les champs. Le Clan du Brouillard tient le fond des vallons, où les sources forment des marais.</p>\n          <p>Autour de la réserve, le reste du parc est ouvert aux promeneurs, aux chasseurs et aux bûcherons. Plus loin, les villages, les fermes, les routes et les terres que personne ne revendique appartiennent aux solitaires, aux chats errants et aux chats domestiques. Les Clans les croisent, les chassent ou les recrutent.</p>\n        </section>\n\n        <section id=\"temps\">\n          <h2>Le temps qui passe</h2>\n          <p>Les chats comptent en lunes. Sur le forum, <b>une lune dure un mois réel</b> : une nouvelle lune se lève le 1<sup>er</sup> de chaque mois, et la Lune 1 correspond à novembre 2026. Les âges, les apprentissages et les saisons suivent ce calendrier.</p>\n          <p>À chaque pleine lune, les quatre Clans se retrouvent au lieu de l’Assemblée. La trêve y est obligatoire : on y échange des nouvelles, pas des coups.</p>\n        </section>\n\n        <section id=\"intrigue\">\n          <h2>L’intrigue</h2>\n          <blockquote class=\"lgdc-gb__prologue\">\n            <p>La brume collait encore aux résineux quand le vieux matou franchit la frontière, boitant, le pelage empestant le sang et la terre froide. Six lunes que le Clan du Crépuscule le pleurait. Les guerriers s’écartèrent, oreilles plaquées. Le revenant ne regarda que la chef. «&nbsp;Ton cœur a beau être de glace, souffla-t-il, un feu s’allumera bientôt à ton flanc. À toi de choisir&nbsp;: te réchauffer, ou te faire consumer.&nbsp;»</p>\n          </blockquote>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"reglement\">\n        <section id=\"inscription\">\n          <h2>L’inscription</h2>\n        <p>Il faut avoir <b>13 ans ou plus</b> pour s’inscrire. C’est l’âge des lecteurs de <i>La Guerre des Clans</i>. Wildheart s’adresse surtout aux adultes qui ont grandi avec les livres, mais les plus jeunes y sont les bienvenus, et le staff veille à les protéger.</p>\n        <p>Les RP peuvent aborder des sujets durs : faites attention à ce que vous lisez, à ce que vous partagez de vous, et prenez soin de vous. Si quelque chose vous met mal à l’aise, parlez-en au staff.</p>\n        <p>Lisez le guidebook en entier avant de poster votre fiche : on part du principe que vous le connaissez.</p>\n        <p>Votre compte porte le nom de votre personnage. Votre pseudo de joueur ou de joueuse se renseigne dans le profil. Si vous manquez d’idée, le <a href=\"#noms\">générateur de noms</a> est là pour vous aider.</p>\n        <p>Après l’inscription, vous avez <b>une semaine</b> pour poster une ébauche de présentation, puis <b>dix jours</b> de plus pour la terminer. Ces délais se prolongent sur simple demande au staff.</p>\n        </section>\n\n        <section id=\"clan\">\n          <h2>Le choix du Clan</h2>\n        <p>Chaque Clan ouvre un nombre limité de places aux joueurs (voir <a href=\"#clans\">Les Clans</a>). Un Clan plein est fermé, sans exception, sauf pour les chatons d’une portée dont au moins un parent est joué.</p>\n        </section>\n\n        <section id=\"activite\">\n          <h2>L’activité</h2>\n        <p>On demande <b>au moins un message RP par lune</b> (un mois réel) pour chaque personnage. Un message dans un sujet en cours suffit.</p>\n        <p>Au début de chaque lune, le staff ouvre un <b>recensement</b> : chaque personnage y confirme sa présence. Un personnage sans message RP pendant une lune et absent du recensement passe aux archives. Il peut revenir à tout moment sur simple demande.</p>\n        <p>Une absence de plus d’une semaine se signale dans le sujet des absences. Un personnage dont l’absence est signalée n’est pas archivé.</p>\n        </section>\n\n        <section id=\"comptes\">\n          <h2>Les multicomptes</h2>\n        <p>Vous pouvez jouer plusieurs personnages, un par compte. Un nouveau compte peut s’ouvrir <b>un mois après la validation</b> de votre dernier personnage.</p>\n        </section>\n\n        <section id=\"avatars\">\n          <h2>Les avatars</h2>\n        <p>Votre avatar peut être <b>un dessin de chat</b>, y compris réalisé sur Picrew ou un outil similaire, <b>une photo réelle de chat</b>, <b>une illustration d’un personnage de la saga officielle <i>La Guerre des Clans</i></b> ou <b>une capture d’écran du jeu WCUE sur Roblox</b>. Pour un dessin, indiquez simplement le nom de l’artiste dans le profil, sans lien. Aucun crédit n’est demandé pour une photo.</p>\n        <p>Un avatar est <b>carré</b>, et fait au moins 250 × 250 pixels. Une image d’un autre format sera recadrée.</p>\n        </section>\n\n        <section id=\"vraisemblance\">\n          <h2>La vraisemblance</h2>\n        <p>Wildheart tient à la vraisemblance : vos personnages sont des chats sauvages, avec leurs limites. Un chaton ne quitte pas le camp seul, ne chasse pas et ne se bat pas contre un adulte. Aucun personnage ne gagne tous ses combats, ne devine les intentions des autres ou n’impose sa loi à toute la forêt.</p>\n        <p>Ce que vous savez en tant que joueur ou joueuse, votre personnage ne le sait pas forcément.</p>\n        </section>\n\n        <section id=\"relations\">\n          <h2>Les relations et les portées</h2>\n        <p>L’inceste est interdit, jusqu’aux cousins inclus. Les relations amoureuses entre un mentor et son apprenti sont interdites, y compris une fois l’apprentissage terminé.</p>\n        <p>Le nombre de chatons d’une portée se tire au dé.</p>\n        </section>\n\n        <section id=\"contenu\">\n          <h2>Ce qu’on peut écrire</h2>\n        <p>Les combats, les blessures et les morts font partie de la vie des Clans. Un message qui contient une scène violente ou difficile commence par la balise <code>&lt;tw&gt;…&lt;/tw&gt;</code>, avec la liste de ce qu’il contient. Par exemple, <code>&lt;tw&gt;sang, mort d’un personnage&lt;/tw&gt;</code> s’affiche ainsi :</p>\n        <tw>sang, mort d’un personnage</tw>\n        <p>Pas de contenu sexuel, ni explicite ni suggéré. Pas de contenu discriminatoire, en RP comme hors RP.</p>\n        </section>\n\n        <section id=\"predefinis\">\n          <h2>Les prédéfinis</h2>\n        <p>Les prédéfinis ne se réservent pas : le premier ou la première à poster sa fiche le prend.</p>\n        </section>\n\n        <section id=\"respect\">\n          <h2>Entre membres</h2>\n        <p>On ne contrôle pas le personnage de quelqu’un d’autre sans son accord : pas de coup qui touche à coup sûr, pas de réaction écrite à sa place. Les conflits entre personnages restent en RP.</p>\n        <p>Le plagiat entraîne la suppression du sujet concerné. Pour toute question ou tout problème, un message privé au staff suffit.</p>\n        <p>Les mêmes règles s’appliquent sur le Discord du forum.</p>\n        </section>\n\n        <section id=\"sanctions\">\n          <h2>Sanctions et évolutions</h2>\n        <p>Les sanctions sont laissées à l’appréciation du staff, selon la gravité des faits. Ce règlement peut évoluer : les changements sont annoncés dans le forum des annonces.</p>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"clans\">\n        <section id=\"relations\">\n          <h2>Les relations</h2>\n          <figure class=\"lgdc-gbm\">\n            <div class=\"lgdc-gbm__map\" role=\"img\" aria-label=\"Clan du Crépuscule et Clan du Brouillard : alliés. Clan du Crépuscule et Clan du Hêtre : neutres. Clan du Crépuscule et Clan de l’Orchidée : ennemis. Clan du Hêtre et Clan de l’Orchidée : alliés. Clan du Hêtre et Clan du Brouillard : ennemis. Clan de l’Orchidée et Clan du Brouillard : neutres.\">\n              <svg viewBox=\"0 0 600 340\" aria-hidden=\"true\"><line class=\"lgdc-gbm__l lgdc-gbm__l--aime\" x1=\"110\" y1=\"70\" x2=\"490\" y2=\"270\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--neutre\" x1=\"110\" y1=\"70\" x2=\"490\" y2=\"70\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--deteste\" x1=\"110\" y1=\"70\" x2=\"110\" y2=\"270\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--aime\" x1=\"490\" y1=\"70\" x2=\"110\" y2=\"270\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--deteste\" x1=\"490\" y1=\"70\" x2=\"490\" y2=\"270\"/><line class=\"lgdc-gbm__l lgdc-gbm__l--neutre\" x1=\"110\" y1=\"270\" x2=\"490\" y2=\"270\"/></svg>\n              <ul aria-hidden=\"true\"><li style=\"--g1:#8e7f9a;--g2:#b59ab8;left:18.333333333333332%;top:20.58823529411765%\"><span class=\"lgdc-ring lgdc-ring--lg\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-crepuscule)\" aria-hidden=\"true\"></span></span></span><span class=\"lgdc-gbm__name\">Crépuscule</span></li><li style=\"--g1:#b07a4f;--g2:#c99566;left:81.66666666666667%;top:20.58823529411765%\"><span class=\"lgdc-ring lgdc-ring--lg\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-hetre)\" aria-hidden=\"true\"></span></span></span><span class=\"lgdc-gbm__name\">Hêtre</span></li><li style=\"--g1:#c2a24f;--g2:#d1b46a;left:18.333333333333332%;top:79.41176470588235%\"><span class=\"lgdc-ring lgdc-ring--lg\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-orchidee)\" aria-hidden=\"true\"></span></span></span><span class=\"lgdc-gbm__name\">Orchidée</span></li><li style=\"--g1:#8a99a4;--g2:#7fa39a;left:81.66666666666667%;top:79.41176470588235%\"><span class=\"lgdc-ring lgdc-ring--lg\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-brouillard)\" aria-hidden=\"true\"></span></span></span><span class=\"lgdc-gbm__name\">Brouillard</span></li></ul>\n            </div>\n            <figcaption class=\"lgdc-gbm__legend\"><span class=\"lgdc-gbm__k lgdc-gbm__k--aime\">Alliés</span><span class=\"lgdc-gbm__k lgdc-gbm__k--neutre\">Neutres</span><span class=\"lgdc-gbm__k lgdc-gbm__k--deteste\">Ennemis</span></figcaption>\n          </figure>\n        </section>\n\n        <section id=\"quatre\">\n          <h2>Les quatre Clans</h2>\n          <p>Chaque Clan compte bien plus de chats que de personnages joués : la plupart de ses membres sont des PNJ. Pour garder les Clans équilibrés, chacun ouvre pour l’instant <b>vingt-six places</b> aux joueurs. Ce nombre augmentera quand les quatre Clans seront bien remplis, sans compter les portées à venir.</p>\n          <p>Comme au début des livres, chaque Clan liste ses membres joués, rôle par rôle. Les places se répartissent de la même façon dans les quatre Clans. Un rôle complet est fermé, sauf pour les chatons d’une portée dont au moins un parent est joué.</p>\n          <p>Les traits de chaque Clan décrivent sa culture, pas le caractère obligatoire de chacun de ses membres.</p>\n          <div class=\"lgdc-gbc\">\n            <input type=\"radio\" name=\"lgdc-gbc\" id=\"lgdc-gbc-crepuscule\" class=\"lgdc-gb__radio\" autocomplete=\"off\" checked><input type=\"radio\" name=\"lgdc-gbc\" id=\"lgdc-gbc-hetre\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbc\" id=\"lgdc-gbc-orchidee\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbc\" id=\"lgdc-gbc-brouillard\" class=\"lgdc-gb__radio\" autocomplete=\"off\">\n            <div class=\"lgdc-gbc__tabs\"><label for=\"lgdc-gbc-crepuscule\" style=\"--g1:#8e7f9a\">Crépuscule</label><label for=\"lgdc-gbc-hetre\" style=\"--g1:#b07a4f\">Hêtre</label><label for=\"lgdc-gbc-orchidee\" style=\"--g1:#c2a24f\">Orchidée</label><label for=\"lgdc-gbc-brouillard\" style=\"--g1:#8a99a4\">Brouillard</label></div>\n            <div class=\"lgdc-gbc__panels\">\n              <div class=\"lgdc-gbc__panel\" data-clan=\"crepuscule\" style=\"--g1:#8e7f9a;--g2:#b59ab8\">\n                <header class=\"lgdc-gbc__head\">\n                  <span class=\"lgdc-ring lgdc-ring--lg\" style=\"--g1:#8e7f9a;--g2:#b59ab8\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-crepuscule)\" aria-hidden=\"true\"></span></span></span>\n                  <div><h3 class=\"lgdc-gbc__name\">Clan du Crépuscule</h3><p class=\"lgdc-gbc__traits\">Disciplinés, vigilants, endurants, froids &amp; inflexibles.</p></div>\n                </header>\n                <dl class=\"lgdc-gbc__facts\">\n                  <div><dt>Territoire</dt><dd>Les rochers du plateau</dd></div>\n                  <div><dt>Places libres</dt><dd>26 / 26</dd></div>\n                </dl>\n                <section class=\"lgdc-gbc__sec\"><h4>Alimentation</h4><p>Lézards des murailles, campagnols et lérots débusqués entre les pierres, oiseaux qui nichent dans les falaises. Les lapins se chassent sur le plateau, au bord des rochers.</p></section><section class=\"lgdc-gbc__sec\"><h4>Spécificité</h4><p>Des guetteurs se relaient jour et nuit sur les hauteurs, d’où l’on voit venir n’importe quelle patrouille. Les apprentis apprennent à se battre en groupe avant d’apprendre à se battre seuls.</p></section><section class=\"lgdc-gbc__sec\"><h4>Tradition</h4><p>Un nouveau guerrier passe sa veillée seul, sur le plus haut rocher du territoire, face au vent. S’il descend avant l’aube, il recommence la nuit suivante.</p></section><section class=\"lgdc-gbc__sec\"><h4>Ce qu’ils pensent des autres</h4><dl class=\"lgdc-gbc__list lgdc-gbc__list--avis\"><div><dt>Clan du Hêtre</dt><dd><span class=lgdc-gbc__rel data-rel=neutre>Neutre</span>Respectés pour leur sagesse, mais trop occupés à écouter leurs ancêtres pour être des alliés utiles.</dd></div><div><dt>Clan de l’Orchidée</dt><dd><span class=lgdc-gbc__rel data-rel=deteste>Détesté</span>Des têtes brûlées sans discipline. Leur fougue est tout ce que le Crépuscule a appris à mépriser.</dd></div><div><dt>Clan du Brouillard</dt><dd><span class=lgdc-gbc__rel data-rel=aime>Apprécié</span>Le seul Clan qui sait monter la garde. Le Crépuscule se méfie de leurs ruses, mais respecte leur patience.</dd></div><div><dt>Solitaires</dt><dd>Reconduits à la frontière. Certains sont recrutés, s’ils acceptent d’obéir.</dd></div><div><dt>Chats domestiques</dt><dd>Des chats de ferme rôdent parfois au pied des rochers. Méprisés, pour avoir vendu leur liberté contre un toit.</dd></div></dl></section><section class=\"lgdc-gbc__sec\"><h4>Allégeances</h4><dl class=\"lgdc-gbc__list\"><div><dt>Chef</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Lieutenant</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Apprenti guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Guerriers</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Apprentis</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Reines</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Chatons</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Anciens</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div></dl></section>\n                <a href=\"/groups\" class=\"lgdc-forum-button\">Voir les membres <i class=\"ph-light ph-arrow-right\" aria-hidden=\"true\"></i></a>\n              </div>\n              <div class=\"lgdc-gbc__panel\" data-clan=\"hetre\" style=\"--g1:#b07a4f;--g2:#c99566\">\n                <header class=\"lgdc-gbc__head\">\n                  <span class=\"lgdc-ring lgdc-ring--lg\" style=\"--g1:#b07a4f;--g2:#c99566\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-hetre)\" aria-hidden=\"true\"></span></span></span>\n                  <div><h3 class=\"lgdc-gbc__name\">Clan du Hêtre</h3><p class=\"lgdc-gbc__traits\">Sages, pieux, hospitaliers, bornés &amp; rancuniers.</p></div>\n                </header>\n                <dl class=\"lgdc-gbc__facts\">\n                  <div><dt>Territoire</dt><dd>La futaie de hêtres</dd></div>\n                  <div><dt>Places libres</dt><dd>26 / 26</dd></div>\n                </dl>\n                <section class=\"lgdc-gbc__sec\"><h4>Alimentation</h4><p>Écureuils, mulots, loirs, merles, geais et pigeons ramiers. Les faînes attirent les rongeurs à l’automne, et c’est la saison où le Clan mange le mieux.</p></section><section class=\"lgdc-gbc__sec\"><h4>Spécificité</h4><p>Les meilleurs grimpeurs de la forêt : ils chassent et montent la garde dans les arbres. Leur réserve de plantes médicinales est la plus riche des quatre Clans.</p></section><section class=\"lgdc-gbc__sec\"><h4>Tradition</h4><p>Les morts sont enterrés au pied d’un hêtre, et la première proie de chaque saison est déposée sur leur tombe avant que quiconque ne mange.</p></section><section class=\"lgdc-gbc__sec\"><h4>Ce qu’ils pensent des autres</h4><dl class=\"lgdc-gbc__list lgdc-gbc__list--avis\"><div><dt>Clan du Crépuscule</dt><dd><span class=lgdc-gbc__rel data-rel=neutre>Neutre</span>Des voisins solides, mais froids. Ils respectent le code plus que les ancêtres.</dd></div><div><dt>Clan de l’Orchidée</dt><dd><span class=lgdc-gbc__rel data-rel=aime>Apprécié</span>Bruyants, mais francs : avec eux, on sait toujours à quoi s’en tenir. Le Hêtre les accueille volontiers à sa frontière.</dd></div><div><dt>Clan du Brouillard</dt><dd><span class=lgdc-gbc__rel data-rel=deteste>Détesté</span>Des menteurs et des voleurs. Le Hêtre n’oublie aucun tort, même vieux de plusieurs saisons.</dd></div><div><dt>Solitaires</dt><dd>Un solitaire blessé ou affamé est soigné et nourri une nuit, puis raccompagné à la frontière.</dd></div><div><dt>Chats domestiques</dt><dd>Au centre de la réserve, le Hêtre n’en voit presque jamais. Il les plaint plus qu’il ne les craint.</dd></div></dl></section><section class=\"lgdc-gbc__sec\"><h4>Allégeances</h4><dl class=\"lgdc-gbc__list\"><div><dt>Chef</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Lieutenant</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Apprenti guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Guerriers</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Apprentis</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Reines</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Chatons</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Anciens</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div></dl></section>\n                <a href=\"/groups\" class=\"lgdc-forum-button\">Voir les membres <i class=\"ph-light ph-arrow-right\" aria-hidden=\"true\"></i></a>\n              </div>\n              <div class=\"lgdc-gbc__panel\" data-clan=\"orchidee\" style=\"--g1:#c2a24f;--g2:#d1b46a\">\n                <header class=\"lgdc-gbc__head\">\n                  <span class=\"lgdc-ring lgdc-ring--lg\" style=\"--g1:#c2a24f;--g2:#d1b46a\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-orchidee)\" aria-hidden=\"true\"></span></span></span>\n                  <div><h3 class=\"lgdc-gbc__name\">Clan de l’Orchidée</h3><p class=\"lgdc-gbc__traits\">Courageux, francs, fougueux, colériques &amp; imprudents.</p></div>\n                </header>\n                <dl class=\"lgdc-gbc__facts\">\n                  <div><dt>Territoire</dt><dd>Les prairies de la lisière</dd></div>\n                  <div><dt>Places libres</dt><dd>25 / 26</dd></div>\n                </dl>\n                <section class=\"lgdc-gbc__sec\"><h4>Alimentation</h4><p>Lapins, campagnols, alouettes, perdrix, et les sauterelles que les chatons apprennent à attraper en premier. On chasse à découvert, à la course.</p></section><section class=\"lgdc-gbc__sec\"><h4>Spécificité</h4><p>Les coureurs les plus rapides des Clans. Les désaccords entre guerriers se règlent par un duel devant le Clan, et l’affaire est close une fois le duel fini.</p></section><section class=\"lgdc-gbc__sec\"><h4>Tradition</h4><p>Avant une bataille, les guerriers se frottent aux orchidées des prairies pour porter tous la même odeur et se reconnaître dans la mêlée.</p></section><section class=\"lgdc-gbc__sec\"><h4>Ce qu’ils pensent des autres</h4><dl class=\"lgdc-gbc__list lgdc-gbc__list--avis\"><div><dt>Clan du Crépuscule</dt><dd><span class=lgdc-gbc__rel data-rel=deteste>Détesté</span>Froids et raides, ils se croient au-dessus des autres. Un guerrier de l’Orchidée ne recule jamais devant eux.</dd></div><div><dt>Clan du Hêtre</dt><dd><span class=lgdc-gbc__rel data-rel=aime>Apprécié</span>Des sages qui parlent beaucoup, mais qui tiennent parole. L’Orchidée les défend volontiers.</dd></div><div><dt>Clan du Brouillard</dt><dd><span class=lgdc-gbc__rel data-rel=neutre>Neutre</span>On ne les comprend pas et on ne leur fait pas confiance, mais tant qu’ils restent dans leur marais, l’Orchidée les laisse tranquilles.</dd></div><div><dt>Solitaires</dt><dd>Jugés sur leur courage : un solitaire qui se bat bien gagne le respect du Clan.</dd></div><div><dt>Chats domestiques</dt><dd>Les prairies bordent des fermes, et leurs chats viennent parfois y chasser. L’Orchidée les chasse à son tour, et s’en moque.</dd></div></dl></section><section class=\"lgdc-gbc__sec\"><h4>Allégeances</h4><dl class=\"lgdc-gbc__list\"><div><dt>Chef</dt><dd><ul><li><a href=\"/profile?mode=editprofile\">Étoile de Faucon</a></li></ul></dd></div><div><dt>Lieutenant</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Apprenti guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Guerriers</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Apprentis</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Reines</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Chatons</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Anciens</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div></dl></section>\n                <a href=\"/groups\" class=\"lgdc-forum-button\">Voir les membres <i class=\"ph-light ph-arrow-right\" aria-hidden=\"true\"></i></a>\n              </div>\n              <div class=\"lgdc-gbc__panel\" data-clan=\"brouillard\" style=\"--g1:#8a99a4;--g2:#7fa39a\">\n                <header class=\"lgdc-gbc__head\">\n                  <span class=\"lgdc-ring lgdc-ring--lg\" style=\"--g1:#8a99a4;--g2:#7fa39a\"><span class=\"lgdc-ring__in\"><span class=\"lgdc-sym\" style=\"--sym:var(--sym-clan-brouillard)\" aria-hidden=\"true\"></span></span></span>\n                  <div><h3 class=\"lgdc-gbc__name\">Clan du Brouillard</h3><p class=\"lgdc-gbc__traits\">Rusés, discrets, débrouillards, sournois &amp; opportunistes.</p></div>\n                </header>\n                <dl class=\"lgdc-gbc__facts\">\n                  <div><dt>Territoire</dt><dd>Les marais des vallons</dd></div>\n                  <div><dt>Places libres</dt><dd>26 / 26</dd></div>\n                </dl>\n                <section class=\"lgdc-gbc__sec\"><h4>Alimentation</h4><p>Grenouilles, poissons des ruisseaux, campagnols amphibies et poules d’eau. Le Clan chasse à l’aube, quand la brume couvre encore le marais.</p></section><section class=\"lgdc-gbc__sec\"><h4>Spécificité</h4><p>Ils nagent, et se roulent dans la boue pour effacer leur odeur. Ils connaissent chaque passage sûr du marais, et laissent les autres s’y enliser.</p></section><section class=\"lgdc-gbc__sec\"><h4>Tradition</h4><p>Les noms de guerrier se donnent à l’aube, quand la brume se lève : le nouveau guerrier sort du brouillard devant le Clan réuni, et c’est la première fois qu’on l’appelle par son nom.</p></section><section class=\"lgdc-gbc__sec\"><h4>Ce qu’ils pensent des autres</h4><dl class=\"lgdc-gbc__list lgdc-gbc__list--avis\"><div><dt>Clan du Crépuscule</dt><dd><span class=lgdc-gbc__rel data-rel=aime>Apprécié</span>Forts et fiables : leurs patrouilles passent toujours à la même heure. Un allié prévisible est un allié utile.</dd></div><div><dt>Clan du Hêtre</dt><dd><span class=lgdc-gbc__rel data-rel=deteste>Détesté</span>Des donneurs de leçons rancuniers, qui ne pardonnent rien. Le Brouillard le leur rend bien.</dd></div><div><dt>Clan de l’Orchidée</dt><dd><span class=lgdc-gbc__rel data-rel=neutre>Neutre</span>Faciles à provoquer, donc faciles à manipuler. Mieux vaut les avoir pour voisins que pour ennemis.</dd></div><div><dt>Solitaires</dt><dd>Des sources de nouvelles. On échange avec eux plus qu’on ne les chasse.</dd></div><div><dt>Chats domestiques</dt><dd>Peu de maisons près du marais, donc peu de rencontres. Le Brouillard écoute ce qu’en racontent les solitaires : tout ce qu’on sait peut servir.</dd></div></dl></section><section class=\"lgdc-gbc__sec\"><h4>Allégeances</h4><dl class=\"lgdc-gbc__list\"><div><dt>Chef</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Lieutenant</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Apprenti guérisseur</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Guerriers</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Apprentis</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Reines</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Chatons</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div><div><dt>Anciens</dt><dd><ul><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li><li class=\"lgdc-gbc__free\">Place libre</li></ul></dd></div></dl></section>\n                <a href=\"/groups\" class=\"lgdc-forum-button\">Voir les membres <i class=\"ph-light ph-arrow-right\" aria-hidden=\"true\"></i></a>\n              </div>\n            </div>\n          </div>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"code\">\n        <section id=\"code-texte\">\n          <h2>Le code du guerrier</h2>\n          <ol class=\"lgdc-gb__code\"><li>Défends ton Clan, même au péril de ta vie. Tu peux être ami avec des guerriers d’autres Clans, mais ta loyauté envers ton Clan doit rester intacte.</li><li>Ne franchis pas les frontières, ne chasse pas sur les territoires des autres Clans.</li><li>Les anciens et les chatons doivent être nourris avant les apprentis et les guerriers.</li><li>Une proie n’est tuée que pour être mangée. Remercie le Clan des Étoiles pour chaque vie que tu prends.</li><li>Un chaton doit être âgé d’au moins six lunes pour devenir apprenti.</li><li>Après son baptême, un guerrier devra observer toute la nuit une veillée silencieuse.</li><li>Un guerrier ne peut devenir lieutenant s’il n’a pas formé au moins un apprenti.</li><li>Le lieutenant deviendra chef du Clan si le chef actuel meurt ou rejoint les anciens.</li><li>Lorsqu’un lieutenant meurt ou rejoint la tanière des anciens, son successeur doit être choisi avant minuit.</li><li>Une Assemblée des Clans se déroule à chaque pleine lune au cours d’une trêve qui dure toute la nuit. Toute forme de violence y est proscrite.</li><li>Les frontières doivent être inspectées et marquées tous les jours. Toute intrusion doit être punie.</li><li>Nul guerrier ne doit ignorer un chaton blessé ou en danger, même si ce chaton vient d’un Clan différent.</li><li>La parole du chef est la loi.</li><li>Un guerrier honorable n’a pas besoin de tuer son ennemi pour remporter la bataille, sauf si cet ennemi ne respecte pas lui-même le Code du guerrier, ou si c’est une question de vie ou de mort.</li><li>Un guerrier doit rejeter la vie facile d’un chat domestique.</li><li>En temps de guerre, tous doivent oublier les frontières et se battre côte à côte afin de préserver les quatre Clans.</li></ol>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"noms\">\n        <section id=\"noms-regles\">\n          <h2>Les noms</h2><div class=\"lgdc-noms\">\n  <section aria-labelledby=\"noms-chatons\">\n    <h3 id=\"noms-chatons\">Les chatons</h3>\n    <p>Le nom d’un chaton peut commencer par <b>« Petit » ou « Petite »</b>, <b>« Patte »</b> ou <b>« Boule »</b>.</p>\n  </section>\n  <section aria-labelledby=\"noms-apprentis\">\n    <h3 id=\"noms-apprentis\">Les apprentis</h3>\n    <p>Tous les noms des apprentis commencent par <b>« Nuage »</b>.</p>\n  </section>\n  <section aria-labelledby=\"noms-chefs\">\n    <h3 id=\"noms-chefs\">Les chefs</h3>\n    <p>Le nom d’un chef commence par <b>« Étoile »</b>.</p>\n  </section>\n  <section class=\"lgdc-noms__generator\" aria-labelledby=\"noms-generateur\">\n    <h3 id=\"noms-generateur\">Générateur de noms</h3>\n    <p><b>L’utilisation du générateur est vivement encouragée.</b> Les éléments proposés ont été triés pour rester cohérents avec l’environnement et les connaissances des Clans, afin d’éviter qu’un nom soit finalement refusé pour une question de réalisme.</p>\n    <p>Les références à la mer, par exemple, demandent une justification cohérente dans l’histoire du personnage : nos chats vivent très loin du littoral.</p>\n    <form id=\"lgdc-noms-form\">\n      <div class=\"lgdc-noms__rang\">\n      <label for=\"lgdc-noms-rang\">Rang du personnage</label>\n      <select id=\"lgdc-noms-rang\" name=\"rang\">\n        <option value=\"chaton\">Chaton</option>\n        <option value=\"apprenti\">Apprenti</option>\n        <option value=\"guerrier\">Guerrier</option>\n        <option value=\"chef\">Chef</option>\n      </select>\n      </div>\n      <div class=\"lgdc-noms__filtres\">\n        <fieldset><legend>Pelage</legend><div class=\"lgdc-noms__choix\"><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-blanc\"> <span>Blanc</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-noir\"> <span>Noir</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-gris\"> <span>Gris</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-brun\"> <span>Brun</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-roux\"> <span>Roux</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-dore\"> <span>Doré</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-creme\"> <span>Crème</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-ecaille\"> <span>Écaille de tortue</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-bicolore\"> <span>Bicolore</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-tigre\"> <span>Tigré</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"pelage-tachete\"> <span>Tacheté</span></label></div></fieldset>\n<fieldset><legend>Yeux</legend><div class=\"lgdc-noms__choix\"><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-verts\"> <span>Verts</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-bleus\"> <span>Bleus</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-ambres\"> <span>Ambrés</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-cuivres\"> <span>Cuivrés</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"yeux-gris\"> <span>Gris</span></label></div></fieldset>\n<fieldset><legend>Caractère</legend><div class=\"lgdc-noms__choix\"><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-gentil\"> <span>Gentil</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-calme\"> <span>Calme</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-courageux\"> <span>Courageux</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-vif\"> <span>Vif</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-discret\"> <span>Discret</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-sage\"> <span>Sage</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"caractere-farouche\"> <span>Farouche</span></label></div></fieldset>\n<fieldset><legend>Vibe de Clan</legend><div class=\"lgdc-noms__choix\"><label><input type=\"checkbox\" name=\"trait\" value=\"clan-crepuscule\"> <span>Crépuscule</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"clan-hetre\"> <span>Hêtre</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"clan-orchidee\"> <span>Orchidée</span></label><label><input type=\"checkbox\" name=\"trait\" value=\"clan-brouillard\"> <span>Brouillard</span></label></div></fieldset>\n      </div>\n      <div class=\"lgdc-noms__actions\">\n        <button class=\"lgdc-forum-button lgdc-forum-button--primary\" type=\"submit\">Générer un nom</button>\n        <button class=\"lgdc-forum-button\" id=\"lgdc-noms-effacer\" type=\"button\">Effacer les filtres</button>\n      </div>\n      <div class=\"lgdc-noms__tirage\" aria-live=\"polite\" aria-atomic=\"true\">\n        <output id=\"lgdc-noms-resultat\">Petite Braise</output>\n        <p id=\"lgdc-noms-selection\"></p>\n      </div>\n    </form>\n    <noscript><p>Active JavaScript pour tirer un autre nom.</p></noscript>\n  </section>\n</div>\n\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"systeme\">\n        <section id=\"sys\">\n          <h2>Le système</h2>\n          <p>Le système s’inspire du <i>Warriors Adventure Game</i>, le jeu de rôle officiel de la saga, et de <i>Fabula Ultima</i>.</p>\n          <div class=\"lgdc-gbc lgdc-gbsy\">\n            <input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-personnage\" class=\"lgdc-gb__radio\" autocomplete=\"off\" checked><input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-tests\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-chasse\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-combat\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbsy\" id=\"lgdc-gbsy-temps\" class=\"lgdc-gb__radio\" autocomplete=\"off\">\n            <div class=\"lgdc-gbc__tabs\"><label for=\"lgdc-gbsy-personnage\">Le personnage</label><label for=\"lgdc-gbsy-tests\">Les tests</label><label for=\"lgdc-gbsy-chasse\">La chasse</label><label for=\"lgdc-gbsy-combat\">Combat et soins</label><label for=\"lgdc-gbsy-temps\">Le temps</label></div>\n            <div class=\"lgdc-gbsy__panels\"><div class=\"lgdc-gbsy__panel\" id=\"sys-personnage\" data-sub=\"personnage\" data-radio=\"lgdc-gbsy-personnage\"><div class=\"lgdc-gbs__block\"><h3>Le principe</h3><p>Sur Wildheart, on écrit d’abord. Les dés ne servent que lorsque l’issue d’une action compte et reste incertaine : une chasse, un combat, un soin difficile, une confrontation à l’Assemblée. Le reste du RP s’écrit librement, et chaque test se lance avec les dés du forum, dans le message de RP.</p></div><div class=\"lgdc-gbs__block\"><h3>Les quatre attributs</h3><p>Chaque attribut est noté par une taille de dé. Plus le dé est gros, plus le chat est doué : <span class=\"lgdc-dice\"><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d12</span></span></p><ul class=\"lgdc-gbs__attrs\"><li><p class=\"lgdc-gbs__attr-n\">Dextérité</p><p class=\"lgdc-gbs__attr-d\">bondir, grimper, esquiver, se faufiler</p></li><li><p class=\"lgdc-gbs__attr-n\">Intelligence</p><p class=\"lgdc-gbs__attr-d\">observer, flairer, comprendre, soigner</p></li><li><p class=\"lgdc-gbs__attr-n\">Puissance</p><p class=\"lgdc-gbs__attr-d\">se battre, plaquer, nager, encaisser</p></li><li><p class=\"lgdc-gbs__attr-n\">Volonté</p><p class=\"lgdc-gbs__attr-d\">tenir bon, feuler, convaincre, affronter la peur</p></li></ul></div><div class=\"lgdc-gbs__block\"><h3>Les dés selon le rang</h3><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs \"><thead><tr><th scope=\"col\">Rang</th><th scope=\"col\">Répartition au choix</th></tr></thead><tbody><tr><td>Chaton</td><td><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span></span></td></tr><tr><td>Apprenti</td><td><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d6</span></span><span class=\"lgdc-gbs__or\">ou</span><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span></span></td></tr><tr><td>Guerrier, guérisseur, lieutenant, chef</td><td><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span></span><span class=\"lgdc-gbs__or\">ou</span><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d8</span><span class=\"lgdc-die\">d6</span></span><span class=\"lgdc-gbs__or\">ou</span><span class=\"lgdc-dice\"><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d10</span><span class=\"lgdc-die\">d6</span><span class=\"lgdc-die\">d6</span></span></td></tr><tr><td>Ancien</td><td>comme un guerrier, puis Dextérité et Puissance perdent une taille, et Intelligence ou Volonté en gagne une</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>Points de vie et esquive</h3><dl class=\"lgdc-gbs__facts\"><div><dt>Points de vie</dt><dd>dé de Puissance + 5 (chaton), + 10 (apprenti) ou + 15 (guerrier et plus)</dd></div><div><dt>Esquive</dt><dd>la taille du dé de Dextérité</dd></div></dl></div><div class=\"lgdc-gbs__block\"><h3>La capacité de Clan</h3><ul class=\"lgdc-gbs__clans\"><li style=\"--g1:#8e7f9a\"><span class=\"lgdc-gbr__clan\">Crépuscule</span><b>+1 en Guetter</b></li><li style=\"--g1:#b07a4f\"><span class=\"lgdc-gbr__clan\">Hêtre</span><b>+1 en Grimper</b></li><li style=\"--g1:#c2a24f\"><span class=\"lgdc-gbr__clan\">Orchidée</span><b>+1 en Bondir</b></li><li style=\"--g1:#8a99a4\"><span class=\"lgdc-gbr__clan\">Brouillard</span><b>+1 en Nager</b></li></ul></div><div class=\"lgdc-gbs__block\"><h3>Les capacités de rôle</h3><p>Elles s’ajoutent aux astuces. Les rôles ne donnent pas de meilleurs dés.</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs \"><thead><tr><th scope=\"col\">Rôle</th><th scope=\"col\">Capacité</th><th scope=\"col\">Condition</th></tr></thead><tbody><tr><td>Lieutenant</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Organiser les patrouilles\" title=\"Une fois par sujet : +2 au test d’un camarade de Clan.\">Organiser les patrouilles</b></td><td>Être guerrier et avoir formé au moins un apprenti.</td></tr><tr><td>Chef</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Neuf vies\" title=\"Perd une vie au lieu de mourir.\">Neuf vies</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"La parole du chef\" title=\"Une fois par sujet : +2 pour Convaincre ou Tenir bon face à son Clan.\">La parole du chef</b></td><td>Avoir été lieutenant.</td></tr><tr><td>Guérisseur</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Lire les signes\" title=\"Interprète les rêves et les présages, sans test.\">Lire les signes</b></td><td>Avoir été apprenti guérisseur.</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>Le modèle de fiche</h3><p>À copier dans le champ « Fiche technique » du profil, puis à compléter :</p><pre class=\"lgdc-gbs__code\">[b]Dextérité[/b] d8, [b]Intelligence[/b] d8, [b]Puissance[/b] d8, [b]Volonté[/b] d8\n[b]Points de vie[/b] 23, [b]Esquive[/b] 8\n[b]Capacité de Clan[/b] +1 en …\n[b]Astuces[/b] …, …, …\n[b]Bonus de gestes[/b] …\n[b]Améliorations[/b] 0 (prochaine à la Lune …)</pre></div></div><div class=\"lgdc-gbsy__panel\" id=\"sys-tests\" data-sub=\"tests\" data-radio=\"lgdc-gbsy-tests\"><div class=\"lgdc-gbs__block\"><h3>Le test</h3><p>On lance <b>les deux dés du geste</b>, on additionne avec les bonus éventuels, et on réussit si le total atteint la difficulté.</p><ol class=\"lgdc-gbs__ladder\"><li><b>7</b><span class=\"lgdc-micro\">Facile</span></li><li><b>10</b><span class=\"lgdc-micro\">Moyen</span></li><li><b>13</b><span class=\"lgdc-micro\">Difficile</span></li><li><b>16</b><span class=\"lgdc-micro\">Très difficile</span></li></ol></div><div class=\"lgdc-gbs__block\"><h3>Les gestes</h3><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--gestes\"><thead><tr><th scope=\"col\">Geste</th><th scope=\"col\">Dés à lancer</th></tr></thead><tbody><tr><td>Guetter (voir, écouter, flairer)</td><td>Intelligence + Volonté</td></tr><tr><td>Pister, Réfléchir</td><td>Intelligence + Intelligence</td></tr><tr><td>Se faufiler</td><td>Dextérité + Volonté</td></tr><tr><td>Bondir (assaut, proie)</td><td>Dextérité + Intelligence</td></tr><tr><td>Frapper (coup de patte)</td><td>Puissance + Puissance</td></tr><tr><td>Grimper</td><td>Dextérité + Puissance</td></tr><tr><td>Mordre</td><td>Puissance + Intelligence</td></tr><tr><td>Nager</td><td>Puissance + Volonté</td></tr><tr><td>Feuler, gonfler le dos</td><td>Volonté + Puissance</td></tr><tr><td>Soigner</td><td>Intelligence + Volonté</td></tr><tr><td>Convaincre</td><td>Volonté + Intelligence</td></tr><tr><td>Tenir bon (peur, douleur)</td><td>Volonté + Volonté</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>Critiques et échecs</h3><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Double de 6 ou plus</b> : critique, c’est une réussite avec un avantage en plus.<br><b>Double 1</b> : échec spectaculaire, et ça tourne mal.</p></aside></div><div class=\"lgdc-gbs__block\"><h3>Les liens</h3><p>Un chat peut avoir autant de liens qu’il veut, avec un personnage ou un groupe. Chaque lien porte au plus une émotion par paire :</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--pairs\"><thead><tr><th scope=\"col\"></th><th scope=\"col\"></th></tr></thead><tbody><tr><td>admiration</td><td>mépris</td></tr><tr><td>loyauté</td><td>méfiance</td></tr><tr><td>affection</td><td>haine</td></tr></tbody></table></div><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Un RP terminé = une émotion gagnée</b> envers un personnage de ce RP. L’émotion opposée remplace l’ancienne.<br>Quand le chat agit pour ou contre la personne liée : <b>+1 par émotion</b>, automatiquement, une fois par sujet.</p></aside></div><div class=\"lgdc-gbs__block\"><h3>Les astuces</h3><p>Un apprenti en a 1, un guerrier 3, choisies dans n’importe quelle voie. Chacune s’utilise <b>une fois par sujet</b>. Survolez une astuce pour lire son effet.</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs \"><thead><tr><th scope=\"col\">Voie</th><th scope=\"col\">Astuces</th></tr></thead><tbody><tr><td>Combattant</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Coup puissant\" title=\"+5 dégâts sur un coup.\">Coup puissant</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Plaquage\" title=\"La cible est ralentie.\">Plaquage</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Griffes au ventre\" title=\"Contre une cible plaquée ou au sol, +3 dégâts.\">Griffes au ventre</b></td></tr><tr><td>Chasseur</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Traque\" title=\"Relancer un test de Se faufiler.\">Traque</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Bond mortel\" title=\"Attraper et tuer en un seul test.\">Bond mortel</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Patience\" title=\"+2 pour Guetter une proie.\">Patience</b></td></tr><tr><td>Gardien</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Vigilance\" title=\"+2 pour Guetter.\">Vigilance</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Rempart\" title=\"Prendre les dégâts d’un camarade.\">Rempart</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Commandement\" title=\"+2 au test d’un allié.\">Commandement</b></td></tr><tr><td>Rôdeur</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Effacer son odeur\" title=\"−2 pour qui la piste.\">Effacer son odeur</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Feinte\" title=\"La cible ne peut pas esquiver.\">Feinte</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Course\" title=\"Fuir sans test.\">Course</b></td></tr><tr><td>Guérisseur</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Connaissance des plantes\" title=\"+2 pour Soigner.\">Connaissance des plantes</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Remède de voyage\" title=\"Utiliser un remède hors du camp.\">Remède de voyage</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Lire les signes\" title=\"Interpréter un rêve ou un présage.\">Lire les signes</b></td></tr><tr><td>Orateur</td><td><b class=\"lgdc-tip\" data-tooltip-head=\"Feulement\" title=\"La cible est effrayée.\">Feulement</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Apaiser\" title=\"Retire l’état « enragé ».\">Apaiser</b>, <b class=\"lgdc-tip\" data-tooltip-head=\"Parole d’Assemblée\" title=\"+2 pour Convaincre devant les Clans.\">Parole d’Assemblée</b></td></tr></tbody></table></div></div></div><div class=\"lgdc-gbsy__panel\" id=\"sys-chasse\" data-sub=\"chasse\" data-radio=\"lgdc-gbsy-chasse\"><div class=\"lgdc-gbs__block\"><h3>Les quatre étapes</h3><p>Une chasse se joue en quatre tests, dans l’ordre, contre la difficulté de la proie.</p><ol class=\"lgdc-gbs__steps\"><li><span class=\"lgdc-micro\">Étape 1</span><b>Guetter</b><span>repérer la proie</span></li><li><span class=\"lgdc-micro\">Étape 2</span><b>Se faufiler</b><span>l’approcher</span></li><li><span class=\"lgdc-micro\">Étape 3</span><b>Bondir</b><span>l’attraper</span></li><li><span class=\"lgdc-micro\">Étape 4</span><b>Mordre</b><span>la tuer</span></li></ol><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Au premier échec, la proie s’enfuit.</b> Un critique permet de sauter l’étape suivante.</p></aside></div><div class=\"lgdc-gbs__block\"><h3>Les proies de la réserve</h3><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--num\"><thead><tr><th scope=\"col\">Proie</th><th scope=\"col\">Guetter</th><th scope=\"col\">Se faufiler</th><th scope=\"col\">Bondir</th><th scope=\"col\">Mordre</th><th scope=\"col\">Points</th></tr></thead><tbody><tr><td>Campagnol, mulot</td><td>10</td><td>7</td><td>7</td><td>7</td><td>1</td></tr><tr><td>Grenouille, lézard</td><td>10</td><td>7</td><td>10</td><td>7</td><td>1</td></tr><tr><td>Oiseau</td><td>7</td><td>10</td><td>13</td><td>7</td><td>1</td></tr><tr><td>Écureuil</td><td>7</td><td>10</td><td>13</td><td>7</td><td>2</td></tr><tr><td>Poisson</td><td>10</td><td>7</td><td>13</td><td>7</td><td>2</td></tr><tr><td>Lapin</td><td>7</td><td>13</td><td>13</td><td>10</td><td>3</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>La pile de gibier du Clan</h3><p>Chaque chasse réussie <b>sur son propre territoire</b> rapporte au Clan les points de la proie. Le joueur l’indique en fin de message : <code>Chasse : lapin (+3)</code>. Le compteur des quatre Clans est affiché dans les annonces.</p><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Objectif : 1 point par membre joué et par lune.</b><br>Objectif raté : tous les membres du Clan commencent la lune suivante <b>affaiblis</b>. Un remède ou une chasse réussie retire l’altération, chat par chat.</p></aside></div><div class=\"lgdc-gbs__block\"><h3>L’évaluation des apprentis</h3><p>Pour devenir guerrier, un apprenti doit réussir une chasse complète devant son mentor, dans un RP. S’il échoue, il réessaiera dans un autre RP.</p></div></div><div class=\"lgdc-gbsy__panel\" id=\"sys-combat\" data-sub=\"combat\" data-radio=\"lgdc-gbsy-combat\"><div class=\"lgdc-gbs__block\"><h3>L’attaque</h3><dl class=\"lgdc-gbs__facts\"><div><dt>Toucher</dt><dd>le test de Frapper, Bondir ou Mordre doit atteindre l’esquive de la cible</dd></div><div><dt>Dégâts</dt><dd>la valeur du plus haut dé + 5 pour les griffes et les morsures</dd></div></dl></div><div class=\"lgdc-gbs__block\"><h3>Tomber</h3><p>Sous la moitié de ses points de vie, le chat est <b>en crise</b>. À 0, son joueur choisit :</p><ul class=\"lgdc-gbs__cards\"><li><b>Se rendre</b><span>Le chat est hors de combat, avec une conséquence pour l’histoire.</span></li><li><b>Se sacrifier</b><span>Un dernier geste, puis il rejoint le Clan des Étoiles.</span></li><li><b>Un chef</b><span>Perd une de ses neuf vies au lieu de tomber.</span></li></ul></div><div class=\"lgdc-gbs__block\"><h3>Les altérations</h3><p>Une altération fait baisser un ou deux dés d’une taille, jusqu’à ce qu’elle soit soignée.</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs \"><thead><tr><th scope=\"col\">Altération</th><th scope=\"col\">Dé touché</th><th scope=\"col\">Remèdes</th></tr></thead><tbody><tr><td>Ralenti</td><td>Dextérité</td><td>consoude, feuilles de sureau</td></tr><tr><td>Désorienté</td><td>Intelligence</td><td>menthe aquatique, mauve</td></tr><tr><td>Affaibli</td><td>Puissance</td><td>pâquerette, pimprenelle, baies de genièvre</td></tr><tr><td>Effrayé</td><td>Volonté</td><td>thym serpolet, valériane</td></tr><tr><td>Enragé</td><td>Dextérité et Intelligence</td><td>graines de pavot</td></tr><tr><td>Empoisonné</td><td>Puissance et Volonté</td><td>achillée mille-feuille, racine de glouteron</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>Les soins</h3><p>Une fois par sujet, le guérisseur fait un test de <b>Soigner</b>. S’il réussit, le blessé récupère la valeur du plus haut dé + 5 points de vie, et le remède adapté retire l’altération. Les remèdes sont décrits dans <a href=\"#remedes\">Les remèdes</a>.</p><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p>Au début de chaque nouveau sujet, un chat retrouve <b>tous ses points de vie</b>, sauf s’il garde une blessure grave décidée en RP.</p></aside></div></div><div class=\"lgdc-gbsy__panel\" id=\"sys-temps\" data-sub=\"temps\" data-radio=\"lgdc-gbsy-temps\"><div class=\"lgdc-gbs__block\"><h3>La progression</h3><p>Les personnages progressent avec le temps, tous au même rythme.</p><aside class=\"lgdc-gbs__key\"><p class=\"lgdc-micro\">À retenir</p><p><b>Toutes les 3 lunes depuis la validation de la fiche : une amélioration.</b><br>Au choix : une astuce de plus, +1 sur un geste (jusqu’à +3), ou un dé qui gagne une taille.</p></aside></div><div class=\"lgdc-gbs__block\"><h3>Les plafonds</h3><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs \"><thead><tr><th scope=\"col\">Rang</th><th scope=\"col\">Dé maximum</th><th scope=\"col\">Astuces maximum</th></tr></thead><tbody><tr><td>Chaton</td><td><span class=\"lgdc-die\">d8</span></td><td>1</td></tr><tr><td>Apprenti</td><td><span class=\"lgdc-die\">d10</span></td><td>3</td></tr><tr><td>Guerrier, guérisseur, lieutenant, chef</td><td><span class=\"lgdc-die\">d12</span></td><td>6</td></tr><tr><td>Ancien</td><td><span class=\"lgdc-die\">d12</span> Intelligence et Volonté, <span class=\"lgdc-die\">d8</span> Dextérité et Puissance</td><td>6</td></tr></tbody></table></div><p>Ce qui dépasse le plafond est gardé jusqu’au changement de rang, qui se fait en RP et est validé par le staff.</p></div><div class=\"lgdc-gbs__block\"><h3>Les personnages créés plus âgés</h3><p>Une amélioration par tranche de 12 lunes au-delà de 12 lunes, avec un maximum de 4.</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--num\"><thead><tr><th scope=\"col\">Âge à la création</th><th scope=\"col\">12–23</th><th scope=\"col\">24–35</th><th scope=\"col\">36–47</th><th scope=\"col\">48–59</th><th scope=\"col\">60 et +</th></tr></thead><tbody><tr><td>Améliorations</td><td>0</td><td>1</td><td>2</td><td>3</td><td>4</td></tr></tbody></table></div></div><div class=\"lgdc-gbs__block\"><h3>Les portées</h3><p>Une fois par lune, une chatte de plus de 12 lunes peut avoir une portée, si les deux joueurs du couple sont d’accord et si elle n’est ni pleine ni en train d’allaiter. Le nombre de chatons se tire sur un d100 :</p><div class=\"lgdc-gbs__wrap\"><table class=\"lgdc-gbs lgdc-gbs--num\"><thead><tr><th scope=\"col\">d100</th><th scope=\"col\">01–04</th><th scope=\"col\">05–14</th><th scope=\"col\">15–34</th><th scope=\"col\">35–59</th><th scope=\"col\">60–79</th><th scope=\"col\">80–91</th><th scope=\"col\">92–97</th><th scope=\"col\">98–00</th></tr></thead><tbody><tr><td>Chatons</td><td>1</td><td>2</td><td>3</td><td>4</td><td>5</td><td>6</td><td>7</td><td>8</td></tr></tbody></table></div><p>Le staff donne à chaque chaton une apparence générale selon la génétique des parents. Les quotas ne s’appliquent pas aux chatons d’un parent joué.</p></div></div></div>\n          </div>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"remedes\">\n        <section id=\"remedes-liste\">\n          <h2>Les remèdes</h2>\n          <p>Les guérisseurs ne cueillent que ce qui pousse dans la réserve et à ses lisières. Chaque plante indique le territoire où on la trouve le plus souvent.</p>\n          <div class=\"lgdc-gbc lgdc-gbr\">\n            <input type=\"radio\" name=\"lgdc-gbr\" id=\"lgdc-gbr-blessures\" class=\"lgdc-gb__radio\" autocomplete=\"off\" checked><input type=\"radio\" name=\"lgdc-gbr\" id=\"lgdc-gbr-maladies\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbr\" id=\"lgdc-gbr-poisons\" class=\"lgdc-gb__radio\" autocomplete=\"off\"><input type=\"radio\" name=\"lgdc-gbr\" id=\"lgdc-gbr-autres\" class=\"lgdc-gb__radio\" autocomplete=\"off\">\n            <div class=\"lgdc-gbc__tabs\"><label for=\"lgdc-gbr-blessures\">Blessures</label><label for=\"lgdc-gbr-maladies\">Maladies</label><label for=\"lgdc-gbr-poisons\">Poisons</label><label for=\"lgdc-gbr-autres\">Autres usages</label></div>\n            <div class=\"lgdc-gbr__panels\"><ul class=\"lgdc-gbr__panel\" data-cat=\"blessures\"><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Achillea%20millefolium%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-149.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Achillée mille-feuille</h3><p class=\"lgdc-gbr__lat\">Achillea millefolium</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Fleurs blanches en bouquets. Feuilles très fines et coupées.</dd></div><div><dt>Comment</dt><dd>Manger pour faire vomir ou appliquer comme cataplasme.</dd></div><div><dt>Effets</dt><dd>Extraire le poison de l’organisme grâce au vomissement. Soigne les égratignures.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Arctium%20spp%20Sturm15.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Bardane</h3><p class=\"lgdc-gbr__lat\">Arctium lappa</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Fleur violette avec des grandes feuilles</dd></div><div><dt>Comment</dt><dd>Frotter la feuille contre la blessure</dd></div><div><dt>Effets</dt><dd>Soigne les démangeaisons et les inflammations</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Ajuga%20reptans0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Bugle rampante</h3><p class=\"lgdc-gbr__lat\">Ajuga reptans</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante basse aux épis de fleurs bleues, qui court sur le sol.</dd></div><div><dt>Comment</dt><dd>Cataplasme de feuilles.</dd></div><div><dt>Effets</dt><dd>Aide les plaies à cicatriser.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Anthriscus%20sylvestris%20%28K%C3%B6hler%27s%20Medizinal-Pflanzen%29.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Cerfeuil</h3><p class=\"lgdc-gbr__lat\">Anthriscus sylvestris</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante à l’odeur douce, aux larges feuilles ressemblant à des fougères et à petites fleurs blanches. Possède des racines marrons et tortueuses.</dd></div><div><dt>Comment</dt><dd>Appliquer la pulpe de la feuille sur la plaie ou la démangeaison. Mâcher la racine pour les maux de ventre.</dd></div><div><dt>Effets</dt><dd>Le suc des feuilles désinfecte les plaies. Les racines apaisent les maux de ventre. Les feuilles apaisent aussi les maux de ventre mais elles sont moins puissantes que les racines.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Chelidonium%20majus0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Chélidoine</h3><p class=\"lgdc-gbr__lat\">Chelidonium majus</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8e7f9a\">Clan du Crépuscule</span>, les rochers du plateau</dd></div><div><dt>À quoi ça ressemble</dt><dd>Une plante à fleur jaune qui a quatre pétales.</dd></div><div><dt>Comment</dt><dd>Le jus doit pénétrer dans l’œil.</dd></div><div><dt>Effets</dt><dd>Apaise et répare les yeux blessés.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Symphytum%20officinale%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-268.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Consoude</h3><p class=\"lgdc-gbr__lat\">Symphytum officinale</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante aux feuilles larges, possédant de petites grappes de fleurs en clochette roses, mauves ou blanches aux grosses racines noueuses. Possède une odeur acide.</dd></div><div><dt>Comment</dt><dd>Souvent utilisée par les anciens, on peut broyer la racine noire pour en faire un cataplasme à appliquer sur la blessure. Les feuilles peuvent être mâcher, réduit en pulpe et appliquer sur une blessure ou envelopper autour d’une patte.</dd></div><div><dt>Effets</dt><dd>Les feuilles mangées ou enveloppées autour d’une patte aide à réparer les os lors de fractures. La pulpe appliquée apaise les plaies et diminue la douleur d’une griffe tordue. Mâcher les feuilles calme les douleurs.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Quercus%20robur0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Feuilles de chêne</h3><p class=\"lgdc-gbr__lat\">Quercus robur</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Feuilles mortes, sèches et ondulées.</dd></div><div><dt>Comment</dt><dd>Les feuilles séchées doivent être stockées dans un endroit sec jusqu’au moment de l’utilisation, elles sont mâchées avec un cataplasme épais et étalées sur une blessure.</dd></div><div><dt>Effets</dt><dd>Soigne les infections.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Billeder%20af%20nordens%20flora%20%28Plate%20230%29%20BHL10459661.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Millepertuis</h3><p class=\"lgdc-gbr__lat\">Hypericum perforatum</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Fleurs jaunes à cinq pétales ; les feuilles, vues à contre-jour, sont percées de petits points clairs.</dd></div><div><dt>Comment</dt><dd>Cataplasme de fleurs.</dd></div><div><dt>Effets</dt><dd>Soigne les brûlures et les plaies.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Urtica%20dioica0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Ortie</h3><p class=\"lgdc-gbr__lat\">Urtica dioica</p>\n                <dl><div><dt>Où</dt><dd>Sur les quatre territoires</dd></div><div><dt>À quoi ça ressemble</dt><dd>Grande plante verte recouverte de poils urticants sur la tige et sur les feuilles. Possède des graines vertes et épineuses.</dd></div><div><dt>Comment</dt><dd>Manger les graines peuvent servir, comme la mille-feuille, à faire vomir. Ses feuilles peuvent être mangées. Ses feuilles ou sa tige peut-être utiliser en cataplasme.</dd></div><div><dt>Effets</dt><dd>Ses graines couverte d’épines permette d’extraire le poison si elle est donnée à des chats ayant mangé de la chair à corbeaux. Ses feuilles peuvent être mangées ou appliquées en cataplasme sur une blessure pour aider les chats ayant de l’œdème. Le cataplasme de la tige peut-être appliqué sur des blessures pour les aider à guérir.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Nordens%20flora%20Rumex%20acetosa.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Oseille</h3><p class=\"lgdc-gbr__lat\">Rumex acetosa</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante haute avec des fleurs rouges et de grosses feuilles, en tas.</dd></div><div><dt>Comment</dt><dd>Mâcher et appliquer sur la blessure. Manger.</dd></div><div><dt>Effets</dt><dd>Le suc permet d’éviter les infections dues aux égratignures (pique à l’application). Herbe fortifiante (pour éviter les sensations de soif).</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Rumex%20obtusifolius%20Sturm48.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Patience</h3><p class=\"lgdc-gbr__lat\">Rumex obtusifolius</p>\n                <dl><div><dt>Où</dt><dd>Sur les quatre territoires</dd></div><div><dt>À quoi ça ressemble</dt><dd>Grandes feuilles vertes.</dd></div><div><dt>Comment</dt><dd>Frotter contre les coussinets.</dd></div><div><dt>Effets</dt><dd>Soulage les irritations.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Taraxacum%20officinale%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-135.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Pissenlit</h3><p class=\"lgdc-gbr__lat\">Taraxacum officinale</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Fleur aux pétales jaunes et à la tige verte</dd></div><div><dt>Comment</dt><dd>Mâcher</dd></div><div><dt>Effets</dt><dd>Le liquide à l’intérieur de la tige est utilisé pour les piqûres d’abeille. Ses racines peuvent être mâchées et utilisées comme des graines de pavot. Peut servir aussi pour arrêter la montée de lait.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Plantago%20major0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Plantain</h3><p class=\"lgdc-gbr__lat\">Plantago major</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Larges feuilles nervurées, plaquées au sol, épi de fleurs brunes.</dd></div><div><dt>Comment</dt><dd>Mâcher les feuilles et les appliquer.</dd></div><div><dt>Effets</dt><dd>Calme les piqûres et aide les petites plaies à se refermer.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Equisetum%20arvense%20Lindman%20DESC.jpeg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Prêle</h3><p class=\"lgdc-gbr__lat\">Equisetum arvense</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Haute plante verte à la tige piquante avec de grandes épines.</dd></div><div><dt>Comment</dt><dd>Utilisée en cataplasme.</dd></div><div><dt>Effets</dt><dd>Permet de traiter les blessures infectées.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Symphytum%20officinale%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-268.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Racine de consoude</h3><p class=\"lgdc-gbr__lat\">Symphytum officinale</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Racines souterraines grosses, noires à l’extérieur, blanc pur à l’intérieur et très cassantes.</dd></div><div><dt>Comment</dt><dd>Mâcher+faire pénétrer les gouttes dans l’œil. Pour une blessure : en faire une pulpe et l’appliquer sur l blessure</dd></div><div><dt>Effets</dt><dd>La racine de Consoude peut aider pour les problèmes visuels ou aider les blessures à guérir</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Arctium%20spp%20Sturm15.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Racine de glouteron</h3><p class=\"lgdc-gbr__lat\">Arctium lappa</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Chardon muni d’une haute tige à l’odeur forte et aux feuilles sombres. La racine possède un goût amère.</dd></div><div><dt>Comment</dt><dd>Déterrer les racines, ôter la terre et les mâcher jusqu’à obtenir une pâte puis utiliser comme cataplasme.</dd></div><div><dt>Effets</dt><dd>Guérit les infections causées par les morsures de rats. Manger la racine peut donner mal au ventre. Réduit la douleur des morsures de rat au point de ne plus la ressentir.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Rubus%20caesius0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Ronce</h3><p class=\"lgdc-gbr__lat\">Rubus fruticosus</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante à fleurs blanc-rosé à cinq pétales. Pousse dans les zones ensoleillées. Les feuilles dégagent une odeur piquante.</dd></div><div><dt>Comment</dt><dd>Faire des feuilles un cataplasme.</dd></div><div><dt>Effets</dt><dd>Apaise la douleur des piqûres d’abeille.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Sanicula%20europaea0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Sanicle</h3><p class=\"lgdc-gbr__lat\">Sanicula europaea</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Feuilles luisantes en main ouverte, petites boules de fleurs blanches.</dd></div><div><dt>Comment</dt><dd>Mâcher les feuilles et les appliquer.</dd></div><div><dt>Effets</dt><dd>Arrête les saignements et referme les plaies.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Kruisspin%20in%20zijn%20web%2C%20RP-P-1921-1932.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Toiles d’araignée</h3>\n                <dl><div><dt>Où</dt><dd>Sur les quatre territoires</dd></div><div><dt>À quoi ça ressemble</dt><dd>Sécrétion blanche que produit l’araignée par sa bouche et son abdomen.</dd></div><div><dt>Comment</dt><dd>Enrouler autour d’une blessure (attention à ne pas ramasser l’araignée avec).</dd></div><div><dt>Effets</dt><dd>Permet d’arrêter une hémorragie, d’absorber le sang d’une blessure pour la garder propre, de faire tenir un cataplasme ou de bander des membres fracturés.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Solidago%20virgaurea0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Verge d’or</h3><p class=\"lgdc-gbr__lat\">Solidago virgaurea</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Petites fleurs jaunes vif rassemblées sur une branche.</dd></div><div><dt>Comment</dt><dd>Appliqué en cataplasme.</dd></div><div><dt>Effets</dt><dd>Guérison des plaies.</dd></div></dl></div></li></ul><ul class=\"lgdc-gbr__panel\" data-cat=\"maladies\"><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Allium%20ursinum0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Ail des ours</h3><p class=\"lgdc-gbr__lat\">Allium ursinum</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Odeur d’ail extrêmement forte et piquante. Pousse en touffes et possède généralement un bulbe blanc avec des feuilles vertes. Elle peut également produire une fleur.</dd></div><div><dt>Comment</dt><dd>Se rouler dedans.</dd></div><div><dt>Effets</dt><dd>Infections (particulièrement celles causées par les morsures de rats), masque les odeurs.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Juniperus%20communis%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-082.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Baies de genièvre</h3><p class=\"lgdc-gbr__lat\">Juniperus communis</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8e7f9a\">Clan du Crépuscule</span>, les rochers du plateau</dd></div><div><dt>À quoi ça ressemble</dt><dd>Baies bleues pourpres poussant sur un genévrier, un buisson aux feuilles hérissées verts foncées. Possède une forte odeur.</dd></div><div><dt>Comment</dt><dd>Mâcher puis manger. En cataplasme.</dd></div><div><dt>Effets</dt><dd>Redonnent des forces, aide à la respiration et apaisent les maux de ventre. Permet également de calmer les chats.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Matricaria%20chamomilla0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Camomille</h3><p class=\"lgdc-gbr__lat\">Matricaria chamomilla</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Fleur aux pétales blancs et au centre jaune. Pousse en tas.</dd></div><div><dt>Comment</dt><dd>Manger.</dd></div><div><dt>Effets</dt><dd>Diminue la fièvre, renforce le cœur et apaise l’esprit. Herbe fortifiante. Aide à lutter contre la fatigue et facilite la digestion.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Rubus%20idaeus%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-124.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Feuilles de framboisier</h3><p class=\"lgdc-gbr__lat\">Rubus idaeus</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Feuilles aux bords dentelés et douces au toucher.</dd></div><div><dt>Comment</dt><dd>Manger la pulpe des feuilles ou les mâcher. Appuyer sur la plaie avec les feuilles.</dd></div><div><dt>Effets</dt><dd>Pourrait possiblement apaiser la douleur et stopper l’hémorragie lors de la mise bas.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Sambucus%20nigra%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-127.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Feuilles de sureau</h3><p class=\"lgdc-gbr__lat\">Sambucus nigra</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Feuilles à l’extrémité pointue et au bord denté.</dd></div><div><dt>Comment</dt><dd>Utilisé en cataplasme.</dd></div><div><dt>Effets</dt><dd>Soulage les problèmes d’articulations.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Papaver%20rhoeas%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-101.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Graines de pavot</h3><p class=\"lgdc-gbr__lat\">Papaver rhoeas</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Minuscules graines noires rondes récoltées en secouant une fleur de coquelicot séchée.</dd></div><div><dt>Comment</dt><dd>Mâcher.</dd></div><div><dt>Effets</dt><dd>Elles peuvent aider un chat à dormir, calmer des chocs ou le stress, apaiser la douleur. Ne sont pas recommandées pour des reines allaitantes.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Nepeta%20cataria%20Sturm24.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Herbe à chat</h3><p class=\"lgdc-gbr__lat\">Nepeta cataria</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8e7f9a\">Clan du Crépuscule</span>, les rochers du plateau</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante qui émane une délicieuse et attirante odeur dont les feuilles, douce au touché, sont semblables à celles des orties mais ne piquent pas. Elle est facilement brûlée par le gel.</dd></div><div><dt>Comment</dt><dd>Doit être mangée.</dd></div><div><dt>Effets</dt><dd>Soigne les chats atteints du mal blanc ou du mal vert qui peut être mortelle pour les chatons et les anciens. Pourrait devenir dangereux à des doses élevées.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Malva%20sylvestris%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-222.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Mauve</h3><p class=\"lgdc-gbr__lat\">Malva sylvestris</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Fleur avec des pétales blancs et un pistil violet. Possède de grandes feuilles douces au toucher et a une odeur douce et agréable.</dd></div><div><dt>Comment</dt><dd>Les feuilles sont utilisées.</dd></div><div><dt>Effets</dt><dd>Utiliser pour traiter la toux.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Mentha%20aquatica%20%E2%80%94%20Flora%20Batava%20%E2%80%94%20Volume%20v3.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Menthe aquatique</h3><p class=\"lgdc-gbr__lat\">Mentha aquatica</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Petite plante aux feuilles vertes et rondes, et aux fleurs rose clair.</dd></div><div><dt>Comment</dt><dd>Mâcher en pulpe.</dd></div><div><dt>Effets</dt><dd>Très utile contre les maux de ventre.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Bijen%20en%20wespen%20X%2C%20RP-P-1896-A-19368-677.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Miel</h3>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Liquide doré et sucré produit par les abeilles.</dd></div><div><dt>Comment</dt><dd>Doit être mangé. Déposé sur une blessure.</dd></div><div><dt>Effets</dt><dd>Apaise les maux de gorge et aide à respirer quand on a inhalé de la fumée. Peut aussi être utilisé pour donner des forces aux reines lors de la mise bas.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Billeder%20af%20nordens%20flora%20%281917%29%20%2819750123373%29.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Mouron des oiseaux</h3><p class=\"lgdc-gbr__lat\">Stellaria media</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante grimpante avec des petites fleurs aux pétales blancs</dd></div><div><dt>Comment</dt><dd>Manger comme l’Herbe à Chat</dd></div><div><dt>Effets</dt><dd>Traite le Mal Vert mais elle est moins puissante que l’Herbe à Chat</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Sanguisorba%20minor0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Pimprenelle</h3><p class=\"lgdc-gbr__lat\">Sanguisorba minor</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8e7f9a\">Clan du Crépuscule</span>, les rochers du plateau</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante à multiples feuilles vertes ondulées.</dd></div><div><dt>Comment</dt><dd>Manger.</dd></div><div><dt>Effets</dt><dd>Herbe fortifiante. Donne des forces.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Pulmonaria%20officinalis0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Pulmonaire</h3><p class=\"lgdc-gbr__lat\">Pulmonaria officinalis</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Fleur mauve aux larges feuilles vert foncé moucheté de gris</dd></div><div><dt>Comment</dt><dd>Inconnu</dd></div><div><dt>Effets</dt><dd>Soigne le Mal Jaune</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Bellis%20perennis.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Pâquerette</h3><p class=\"lgdc-gbr__lat\">Bellis perennis</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Fleurs aux pétales blancs et au cœur jaune.</dd></div><div><dt>Comment</dt><dd>Mâcher les feuilles pour transformer en cataplasme. Manger (herbe fortifiante).</dd></div><div><dt>Effets</dt><dd>Fortifie l’organisme et augmente les forces. Assouplit les articulations. Herbe fortifiante.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Filipendula%20ulmaria0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Reine-des-prés</h3><p class=\"lgdc-gbr__lat\">Filipendula ulmaria</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Haute plante aux bouquets mousseux de fleurs crème, au parfum de miel.</dd></div><div><dt>Comment</dt><dd>Mâcher les fleurs ou les feuilles.</dd></div><div><dt>Effets</dt><dd>Fait baisser la fièvre et calme les douleurs.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Fagus%20sylvatica%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-060.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Sève de hêtre</h3><p class=\"lgdc-gbr__lat\">Fagus sylvatica</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Sève d’un grand et vieille arbre à l’écorce sèche à sa base. Elle possède une odeur similaire à la sève pin, mais en plus doux..</dd></div><div><dt>Comment</dt><dd>Avaler.</dd></div><div><dt>Effets</dt><dd>Guérie tout type de toux. Elle est plus puissante que l’herbe à chat.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Senecio%20jacobaea.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Séneçon jacobée</h3><p class=\"lgdc-gbr__lat\">Jacobaea vulgaris</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante à fleurs jaunes aux feuilles pennées.</dd></div><div><dt>Comment</dt><dd>Mâcher et appliquer en cataplasme. Manger.</dd></div><div><dt>Effets</dt><dd>En manger trop donne des maux de ventre. Peut traiter les douleurs articulaires quand mélanger avec des baies de genièvre. Fortifie les chats.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Tanacetum%20vulgare0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Tanaisie</h3><p class=\"lgdc-gbr__lat\">Tanacetum vulgare</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante à fleurs rondes et jaunes à l’odeur forte.</dd></div><div><dt>Comment</dt><dd>Mangeable (mais toxique et hallucinogène, mortelle à forte dose).</dd></div><div><dt>Effets</dt><dd>Utilisée pour guérir la toux.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Thymus%20serpyllum%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-138.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Thym serpolet</h3><p class=\"lgdc-gbr__lat\">Thymus serpyllum</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8e7f9a\">Clan du Crépuscule</span>, les rochers du plateau</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plantes à tige marron et à feuilles vert clair, gondolées</dd></div><div><dt>Comment</dt><dd>A faire respirer</dd></div><div><dt>Effets</dt><dd>Calme l’anxiété et la nervosité. Pour les chats en état de choc.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Tussilago%20farfara%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-142.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Tussilage</h3><p class=\"lgdc-gbr__lat\">Tussilago farfara</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8e7f9a\">Clan du Crépuscule</span>, les rochers du plateau</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante à fleurs blanches ou jaunes, semblable au pissenlit. Pousse mieux à la Saison des Feuilles Nouvelles.</dd></div><div><dt>Comment</dt><dd>Mâcher les feuilles pour en faire une pulpe à avaler ou en faire un cataplasme.</dd></div><div><dt>Effets</dt><dd>Facilite la respiration ou la \"toux des chatons\". Soigne aussi bien que les coussinets craquelés ou douloureux.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Valeriana%20officinalis%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-143.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Valériane</h3><p class=\"lgdc-gbr__lat\">Valeriana officinalis</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Grande tige aux fleurs roses en ombelle ; la racine sent fort, et les chats l’adorent.</dd></div><div><dt>Comment</dt><dd>Mâcher la racine.</dd></div><div><dt>Effets</dt><dd>Calme et aide à dormir. Trop en donner rend le chat agité.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Salix%20alba0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Écorce de saule</h3><p class=\"lgdc-gbr__lat\">Salix alba</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Tronc rugueux et irrégulier.</dd></div><div><dt>Comment</dt><dd>Avaler le suc.</dd></div><div><dt>Effets</dt><dd>Apaise la douleur.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Alnus%20glutinosa0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Écorce d’aulne</h3><p class=\"lgdc-gbr__lat\">Alnus glutinosa</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Écorce gris/brunâtre. Les aulnes plus jeunes ont l’écorce plus claire.</dd></div><div><dt>Comment</dt><dd>Mâcher.</dd></div><div><dt>Effets</dt><dd>Soulage les maux de dents.</dd></div></dl></div></li></ul><ul class=\"lgdc-gbr__panel\" data-cat=\"poisons\"><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Arum%20maculatum0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Arum tacheté</h3><p class=\"lgdc-gbr__lat\">Arum maculatum</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Feuilles en fer de lance, grappe de baies rouge vif en fin d’été.</dd></div><div><dt>Comment</dt><dd>Aucun.</dd></div><div><dt>Effets</dt><dd>Brûle la bouche et la gorge, fait gonfler la langue.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Ilex%20aquifolium0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Baies de houx</h3><p class=\"lgdc-gbr__lat\">Ilex aquifolium</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Arbrisseau à feuilles épineuses qui produit des fruits rouges non médicinaux.</dd></div><div><dt>Comment</dt><dd>Baies empoisonnées.</dd></div><div><dt>Effets</dt><dd>Poison. Tue un chat en quelques minutes.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Taxus%20baccata0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Baies d’if</h3><p class=\"lgdc-gbr__lat\">Taxus baccata</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8e7f9a\">Clan du Crépuscule</span>, les rochers du plateau</dd></div><div><dt>À quoi ça ressemble</dt><dd>Baie rouge-rose à l’intérieur noir.</dd></div><div><dt>Comment</dt><dd>Utilisée pour tuer certains chats.</dd></div><div><dt>Effets</dt><dd>Tue un chat en quelques minutes ou soigne les infections dues aux griffures d’une clôture en fer.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Atropa%20belladonna%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-018.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Belladone</h3><p class=\"lgdc-gbr__lat\">Atropa belladonna</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Petit arbuste avec des fleurs en forme de cloche dont les baies sont brillantes et noires à maturité</dd></div><div><dt>Comment</dt><dd>Utiliser pour soigner une grande infection sur un chat en ne mangeant que la chair. Manger la graine provoque la mort.</dd></div><div><dt>Effets</dt><dd>Mort</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Daphne%20mezereum%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-050.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Bois-joli</h3><p class=\"lgdc-gbr__lat\">Daphne mezereum</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Petit arbuste aux fleurs roses qui s’ouvrent avant les feuilles, baies rouges.</dd></div><div><dt>Comment</dt><dd>Aucun.</dd></div><div><dt>Effets</dt><dd>Brûlures de la bouche, convulsions, mort.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/35%20Digitalis%20lutea%20-%20John%20Lindley%20-%20Collectanea%20botanica%20%281821%29.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Digitale jaune</h3><p class=\"lgdc-gbr__lat\">Digitalis lutea</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Hautes tiges couvertes de petites cloches jaune pâle.</dd></div><div><dt>Comment</dt><dd>Aucun : les graines tuent.</dd></div><div><dt>Effets</dt><dd>Ralentit le cœur jusqu’à l’arrêter.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Conium%20maculatum%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-191.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Grande ciguë</h3><p class=\"lgdc-gbr__lat\">Conium maculatum</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Haute plante aux petites fleurs blanches en ombrelles, à la tige tachée de pourpre. Odeur de souris.</dd></div><div><dt>Comment</dt><dd>Aucun.</dd></div><div><dt>Effets</dt><dd>Paralysie, puis mort.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Convallaria%20majalis%20-%20K%C3%B6hler%E2%80%93s%20Medizinal-Pflanzen-045.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Muguet</h3><p class=\"lgdc-gbr__lat\">Convallaria majalis</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Petites clochettes blanches parfumées, baies rouges en été.</dd></div><div><dt>Comment</dt><dd>Aucun.</dd></div><div><dt>Effets</dt><dd>Vomissements, cœur affolé, parfois la mort.</dd></div></dl></div></li></ul><ul class=\"lgdc-gbr__panel\" data-cat=\"autres\"><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Galium%20odorata0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Aspérule odorante</h3><p class=\"lgdc-gbr__lat\">Galium odoratum</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Petites fleurs blanches en étoile, feuilles en collerette. Sent le foin une fois séchée.</dd></div><div><dt>Comment</dt><dd>Glisser dans la litière.</dd></div><div><dt>Effets</dt><dd>Parfume les nids et éloigne les puces.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Die%20S%C3%A4ugthiere%20in%20Abbildungen%20nach%20der%20Natur%2C%20mit%20Beschreibungen%20%28Plate%20CLXXXI%29%20%288610004476%29.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Bile de souris</h3>\n                <dl><div><dt>Où</dt><dd>Sur les quatre territoires</dd></div><div><dt>À quoi ça ressemble</dt><dd>Liquide nauséabond et vert-jaune. Elle a un mauvais goût et aussi une très mauvaise odeur.</dd></div><div><dt>Comment</dt><dd>Tapotez la tique avec un petit morceau de mousse plongé dedans. Appliquer sur une blessure.</dd></div><div><dt>Effets</dt><dd>Sert à détacher les tiques du pelage. Peut être mis sur une blessure pour empêcher le blesser de la mordiller.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Hedera%20helix0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Feuilles de lierre</h3><p class=\"lgdc-gbr__lat\">Hedera helix</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Feuilles en forme d’étoiles ou ovales.</dd></div><div><dt>Comment</dt><dd>Emballer des remèdes.</dd></div><div><dt>Effets</dt><dd>Utiliser pour stocker des remèdes en les emballant dans les feuilles.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Galium%20aparine0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Gaillet gratteron</h3><p class=\"lgdc-gbr__lat\">Galium aparine</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#b07a4f\">Clan du Hêtre</span>, la futaie de hêtres</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante aux fruits ronds et verts recouvert de poils crochus.</dd></div><div><dt>Comment</dt><dd>Utiliser les fruits.</dd></div><div><dt>Effets</dt><dd>Aide à maintenir les cataplasmes en place sans blesser peau.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Juncus%20hostii0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Jonc</h3><p class=\"lgdc-gbr__lat\">Juncus effusus</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#8a99a4\">Clan du Brouillard</span>, les marais des vallons</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante avec de longues tiges et des \"fleurs\" marron.</dd></div><div><dt>Comment</dt><dd>Utilisé comme attelle.</dd></div><div><dt>Effets</dt><dd>Permet de lier des fractures.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Illustration%20Convolvulus%20arvensis0.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Liseron</h3><p class=\"lgdc-gbr__lat\">Convolvulus arvensis</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Plante à fleurs bleues ou blanches poussant principalement sur/autour d’autres végétaux. Des feuilles vertes poussent le long de la tige.</dd></div><div><dt>Comment</dt><dd>/</dd></div><div><dt>Effets</dt><dd>Peut aider, avec des bâtons, à maintenir un membre en place lorsqu’il est cassé.</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Mentha%20arvensis%20Lindman%20DESC.png?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Menthe</h3><p class=\"lgdc-gbr__lat\">Mentha arvensis</p>\n                <dl><div><dt>Où</dt><dd><span class=\"lgdc-gbr__clan\" style=\"--g1:#c2a24f\">Clan de l’Orchidée</span>, les prairies de la lisière</dd></div><div><dt>À quoi ça ressemble</dt><dd>Feuilles douces et dentelées qui varient du vert au violet et au jaune. Les fleurs, quant à elles, sont plutôt petites et présentent des nuances de blanc ou de violet.</dd></div><div><dt>Comment</dt><dd>Frotté sur le corps sans vie d’un chat</dd></div><div><dt>Effets</dt><dd>Dissimule l’odeur de la mort</dd></div></dl></div></li><li class=\"lgdc-gbr__card\"><div class=\"lgdc-gbr__img\"><img src=\"https://commons.wikimedia.org/wiki/Special:FilePath/Polytrichum%20commune%20%E2%80%94%20Flora%20Batava%20%E2%80%94%20Volume%20v8.jpg?width=360\" alt=\"\" loading=\"lazy\"></div><div class=\"lgdc-gbr__txt\"><h3>Mousse</h3><p class=\"lgdc-gbr__lat\">Polytrichum commune</p>\n                <dl><div><dt>Où</dt><dd>Sur les quatre territoires</dd></div><div><dt>À quoi ça ressemble</dt><dd>Un végétal spongieux, vert et doux, que l’ont trouve couramment dans les arbres ou les zones marécageuses.</dd></div><div><dt>Comment</dt><dd>—</dd></div><div><dt>Effets</dt><dd>Utilisée pour la litière des chatset utilisée pour contenir des liquides tel que le miel, l’eau ou la bile de souris. La mousse mouillée peut être utilisée pour appliquer une pression contre le saignement.</dd></div></dl></div></li></ul></div>\n          </div>\n          <p class=\"lgdc-gbr__credit\">Planches botaniques du domaine public (Köhler, Thomé, Lindman, Sturm…), via Wikimedia Commons.</p>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"glossaire\">\n        <section id=\"glossaire\">\n          <h2>Glossaire</h2>\n          <p>Les chats des Clans ont leurs propres mots. Ce glossaire vient du wiki de <i>La Guerre des Clans</i>, sans les lieux et les Clans propres aux livres.</p><nav class=\"lgdc-gbg__index\" aria-label=\"Rubriques du glossaire\"><a href=\"#gl-rangs\">Les rangs</a><a href=\"#gl-camp\">Le camp</a><a href=\"#gl-vie\">La vie du Clan</a><a href=\"#gl-dehors\">Hors des Clans</a><a href=\"#gl-maladies\">Les maladies</a><a href=\"#gl-temps\">Le temps</a><a href=\"#gl-mesures\">Les mesures</a><a href=\"#gl-jurons\">Insultes et jurons</a><a href=\"#gl-expressions\">Expressions</a><a href=\"#gl-proverbes\">Proverbes</a></nav>\n        </section>\n\n        <section id=\"gl-rangs\">\n          <h2>Les rangs</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Chef</dt><dd>Chat qui dirige tout le Clan. Il reçoit neuf vies du Clan des Étoiles et prend un nom en « Étoile ».</dd></div><div><dt>Lieutenant</dt><dd>Guerrier qui seconde le chef, organise les patrouilles et le remplace à sa mort ou à sa retraite.</dd></div><div><dt>Guérisseur</dt><dd>Chat qui soigne les blessures et les maladies grâce aux plantes, et reçoit parfois des signes ou des prophéties du Clan des Étoiles.</dd></div><div><dt>Guerrier</dt><dd>Chat adulte qui a terminé sa formation. Une chatte reste guerrière tant qu’elle n’attend pas ou n’allaite pas de petits.</dd></div><div><dt>Mentor</dt><dd>Guerrier qui forme un apprenti.</dd></div><div><dt>Apprenti</dt><dd>Chat d’au moins six lunes qui apprend le métier de guerrier, ou parfois celui de guérisseur.</dd></div><div><dt>Reine</dt><dd>Chatte qui attend ou élève des petits, ou qui reste à la pouponnière pour aider les autres reines.</dd></div><div><dt>Chaton</dt><dd>Chat de moins de six lunes.</dd></div><div><dt>Ancien</dt><dd>Chat qui ne peut plus chasser ni se battre. Très respecté : les apprentis lui apportent à manger, lui retirent ses puces et changent sa litière.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-camp\">\n          <h2>Le camp</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Camp</dt><dd>Lieu de vie principal du Clan.</dd></div><div><dt>Tanière du chef</dt><dd>Tanière qui appartient au chef.</dd></div><div><dt>Tanière du guérisseur</dt><dd>Tanière où vivent le guérisseur et son apprenti, et où l’on soigne les malades.</dd></div><div><dt>Tanière des guerriers</dt><dd>Tanière des guerriers et du lieutenant.</dd></div><div><dt>Tanière des apprentis</dt><dd>Tanière des apprentis.</dd></div><div><dt>Tanière des anciens</dt><dd>Tanière des anciens.</dd></div><div><dt>Pouponnière</dt><dd>Tanière partagée par les reines et leurs chatons.</dd></div><div><dt>Pile de gibier</dt><dd>Endroit, souvent au centre du camp, où les chasseurs déposent leurs proies pour tout le Clan.</dd></div><div><dt>Petit coin</dt><dd>Endroit près du camp où les chats font leurs besoins.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-vie\">\n          <h2>La vie du Clan</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Assemblée</dt><dd>Réunion des quatre Clans à chaque pleine lune, pendant une trêve voulue par le Clan des Étoiles.</dd></div><div><dt>Clan des Étoiles</dt><dd>Les ancêtres morts des Clans, qui veillent sur eux depuis le ciel.</dd></div><div><dt>Toison Argentée</dt><dd>La Voie lactée. Chaque étoile est un chat du Clan des Étoiles.</dd></div><div><dt>Camarade de Clan</dt><dd>Chat du même Clan.</dd></div><div><dt>Patrouille de chasse</dt><dd>Groupe de chats qui chassent pour nourrir le Clan, et qui peuvent repousser les intrus.</dd></div><div><dt>Proie fraîche</dt><dd>Proie tout juste tuée pour être mangée. Les anciens, les chatons, les reines et les malades mangent en premier, puis les guerriers et les apprentis.</dd></div><div><dt>Le partage</dt><dd>Deux chats se toilettent l’un l’autre en échangeant les dernières nouvelles.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-dehors\">\n          <h2>Hors des Clans</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Solitaire</dt><dd>Chat qui vit seul et ne défend pas de territoire.</dd></div><div><dt>Chat errant</dt><dd>Chat souvent hostile, seul ou en bande, sans Bipèdes ni territoire, qui ignore les frontières des Clans.</dd></div><div><dt>Chat domestique</dt><dd>Chat qui vit chez les Bipèdes, souvent avec un collier, et toujours bien nourri.</dd></div><div><dt>Bipède</dt><dd>Humain. Certains solitaires disent aussi « Sans-Fourrure » ou « Deux-Pattes ».</dd></div><div><dt>Petit Bipède</dt><dd>Enfant.</dd></div><div><dt>Maisonnier</dt><dd>Bipède qui possède un chat domestique.</dd></div><div><dt>Coupeur</dt><dd>Vétérinaire.</dd></div><div><dt>Nid de Bipèdes</dt><dd>Maison.</dd></div><div><dt>Territoire des Bipèdes</dt><dd>Village ou ville.</dd></div><div><dt>Chemin du Tonnerre</dt><dd>Route.</dd></div><div><dt>Monstre</dt><dd>Véhicule des Bipèdes.</dd></div><div><dt>Dévoreur d’arbre</dt><dd>Engin de bûcheron.</dd></div><div><dt>Ronce argentée</dt><dd>Fil barbelé.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-maladies\">\n          <h2>Les maladies</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Mal blanc</dt><dd>Maladie contagieuse, surtout chez les chatons, qui peut vite tourner au mal vert.</dd></div><div><dt>Mal vert</dt><dd>Maladie contagieuse, souvent mortelle.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-temps\">\n          <h2>Le temps</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Saison des feuilles nouvelles</dt><dd>Le printemps.</dd></div><div><dt>Saison des feuilles vertes</dt><dd>L’été.</dd></div><div><dt>Saison des feuilles mortes</dt><dd>L’automne.</dd></div><div><dt>Mauvaise saison</dt><dd>L’hiver.</dd></div><div><dt>Saison</dt><dd>Un quart d’année.</dd></div><div><dt>Lune</dt><dd>Un mois.</dd></div><div><dt>Demi-lune</dt><dd>Deux semaines.</dd></div><div><dt>Quart de lune</dt><dd>Une semaine.</dd></div><div><dt>Battement de cœur</dt><dd>Quelques secondes.</dd></div><div><dt>Aube</dt><dd>Le moment qui précède le lever du soleil.</dd></div><div><dt>Lever du soleil</dt><dd>L’aurore.</dd></div><div><dt>Midi</dt><dd>Le soleil au plus haut.</dd></div><div><dt>Coucher du soleil</dt><dd>Le crépuscule du soir.</dd></div><div><dt>Crépuscule</dt><dd>Le lever de la lune.</dd></div><div><dt>Minuit</dt><dd>La lune au plus haut.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-mesures\">\n          <h2>Les mesures</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Longueur de souris</dt><dd>Environ 5 à 7 cm.</dd></div><div><dt>Longueur de queue</dt><dd>Environ 30 cm.</dd></div><div><dt>Bond de lapin</dt><dd>Environ 45 cm.</dd></div><div><dt>Longueur de renard</dt><dd>Environ 80 cm.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-jurons\">\n          <h2>Insultes et jurons</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Cervelle de souris</dt><dd>Imbécile. Peut être amical. Variantes : cervelle de lièvre, d’oiseau, de lapin, de puce, d’abeille.</dd></div><div><dt>Boule de poils, cerveau mou</dt><dd>Insultes amicales mais sévères : tout dépend du ton.</dd></div><div><dt>Cœur de renard</dt><dd>Cruel, sans cœur.</dd></div><div><dt>Cœur de souris</dt><dd>Lâche.</dd></div><div><dt>Souris effrayée !</dt><dd>Chat qui a peur de tout.</dd></div><div><dt>Haleine de renard</dt><dd>Chat qui a mauvaise haleine.</dd></div><div><dt>Loir</dt><dd>Chat qui dort beaucoup.</dd></div><div><dt>Face de crotte</dt><dd>Insulte grave et ancienne.</dd></div><div><dt>Peau galeuse</dt><dd>Insulte.</dd></div><div><dt>Patte propre</dt><dd>Chat qui s’en tient strictement aux règles (méprisant).</dd></div><div><dt>Chauve-souris aveugle</dt><dd>Se moque de la vue d’un chat.</dd></div><div><dt>Crotte de souris !</dt><dd>Juron de dégoût ou de déception. Variantes : crotte de lièvre, crotte de renard.</dd></div><div><dt>Par le Clan des Étoiles !</dt><dd>Surprise ou colère extrême. Aussi : « Au nom du Clan des Étoiles ! »</dd></div><div><dt>Dans toutes les étoiles !</dt><dd>Exaspération.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-expressions\">\n          <h2>Expressions</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Chair à corbeau</dt><dd>Nourriture pourrie ou répugnante. Aussi une insulte.</dd></div><div><dt>Qui a ébouriffé sa fourrure ?</dt><dd>Se dit de ce qui agace quelqu’un.</dd></div><div><dt>Aussi utile qu’un renard mort</dt><dd>Totalement inutile.</dd></div><div><dt>Des abeilles te bourdonnent dans le crâne !</dt><dd>Tu dis n’importe quoi.</dd></div><div><dt>Plus fou qu’un renard en crise !</dt><dd>Se dit d’un chat qui agit sans raison.</dd></div><div><dt>Peu importe une moustache</dt><dd>Ça m’est égal. Ou : la patrouille n’a rien attrapé.</dd></div><div><dt>Je n’en donnerais pas une queue de souris</dt><dd>Je m’en moque.</dd></div><div><dt>Comme le Clan du Lion</dt><dd>Avec une férocité ou un courage immenses. Aussi : « comme le Clan du Tigre ».</dd></div><div><dt>Quand les hérissons voleront</dt><dd>Jamais.</dd></div><div><dt>Il fait aussi sombre qu’un cœur de renard</dt><dd>Il fait noir comme dans un four.</dd></div><div><dt>Tu chasses comme un chat domestique !</dt><dd>Moquerie envers un chat qui chasse ou se bat mal.</dd></div><div><dt>Tu aurais fait de la viande de souris !</dt><dd>Je t’aurais mis en lambeaux.</dd></div><div><dt>Seul le Clan des Étoiles le sait</dt><dd>Réponse à une question sans réponse.</dd></div><div><dt>Que le Clan des Étoiles éclaire ton chemin</dt><dd>Bonne chance.</dd></div><div><dt>Bonne chasse, course rapide, et un abri quand tu dors</dt><dd>Très ancien adieu, commun à tous les Clans.</dd></div></dl>\n        </section>\n\n        <section id=\"gl-proverbes\">\n          <h2>Proverbes</h2>\n          <dl class=\"lgdc-gbg\"><div><dt>Mieux vaut effrayer une souris qu’accueillir un blaireau</dt><dd>Mieux vaut faire fuir un ami que laisser entrer un ennemi.</dd></div><div><dt>Chat domestique un jour, chat domestique toujours</dt><dd>Insulte envers un chat d’origine domestique.</dd></div><div><dt>Les excuses, ça ne nourrit pas son chat</dt><dd>S’excuser ne change pas le passé.</dd></div><div><dt>Un chat tigré ne quitte pas ses rayures</dt><dd>On ne change pas sa nature.</dd></div></dl>\n          <p class=\"lgdc-gbg__credit\">Adapté du <a href=\"https://lgdc.fandom.com/fr/wiki/Glossaire\">glossaire du Wiki La Guerre des Clans</a> et de ses contributeurs, sous licence CC BY-SA. Définitions abrégées ; lieux et Clans propres aux livres omis.</p>\n        </section>\n\n      </div>\n\n      <div class=\"lgdc-gb__panel\" data-tab=\"credits\">\n        <section id=\"cr-saga\">\n          <h2>La saga</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt><i>La Guerre des Clans</i></dt><dd>Erin Hunter, éditions Pocket Jeunesse pour la traduction française. Wildheart est un forum de fans, sans lien avec les éditeurs. Le code du guerrier est repris de la traduction officielle.</dd></div><div><dt>Wiki <i>La Guerre des Clans</i></dt><dd><a href=\"https://lgdc.fandom.com/fr/\">lgdc.fandom.com</a>, licence CC BY-SA. Base des remèdes, du glossaire et de la banque du générateur de noms.</dd></div></dl>\n        </section>\n\n        <section id=\"cr-systeme\">\n          <h2>Le système</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt><i>Warriors Adventure Game</i></dt><dd>Working Partners. Le jeu de rôle officiel de la saga, dont s’inspirent les gestes, la chasse et les capacités de Clan.</dd></div><div><dt><i>Fabula Ultima</i></dt><dd>Need Games. Source des attributs en taille de dé, des liens et des altérations.</dd></div></dl>\n        </section>\n\n        <section id=\"cr-reserve\">\n          <h2>La réserve</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt>Parc national de forêts</dt><dd>Le plan de gestion de la réserve intégrale d’Arc-Châteauvillain a servi à vérifier les plantes, les animaux et les noms présents dans la réserve.</dd></div></dl>\n        </section>\n\n        <section id=\"cr-images\">\n          <h2>Les images</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt>Illustrations de chats</dt><dd>Les dessins de chats du forum sont de <a href=\"https://www.tumblr.com/greyratdog\">greyratdog</a>.</dd></div><div><dt>Pleine lune de la bannière</dt><dd>Gregory H. Revera, Wikimedia Commons (« FullMoon2010.jpg »), licence CC BY-SA 3.0.</dd></div><div><dt>Photographies</dt><dd><a href=\"https://unsplash.com/\">Unsplash</a>, licence Unsplash : la brume, la forêt d’automne, et les chats de l’encart du guidebook.</dd></div><div><dt>Planches des remèdes</dt><dd>Domaine public, via Wikimedia Commons : Köhler, <i>Medizinal-Pflanzen</i> (1887) ; Thomé, <i>Flora von Deutschland</i> (1885) ; Sturm, <i>Deutschlands Flora</i> ; Lindman, <i>Bilder ur Nordens Flora</i> ; <i>Flora Batava</i> ; Lindley, <i>Collectanea botanica</i> (1821) ; Schreber, <i>Die Säugthiere</i> ; estampes du Rijksmuseum d’Amsterdam.</dd></div><div><dt>Symboles des Clans</dt><dd>Créations originales pour Wildheart.</dd></div></dl>\n        </section>\n\n        <section id=\"cr-code\">\n          <h2>Le code du forum</h2><dl class=\"lgdc-gbs__facts lgdc-gbcr\"><div><dt>Truesight</dt><dd>This skin uses the tooltip system <b>\"Truesight\"</b> (<a href=\"https://necodemancer.github.io/schoolofnecromancy/truesight/\">Usage guide</a>) made by <a href=\"https://necromancercoding.tumblr.com/\">Necromancer Coding</a>.</dd></div><div><dt>Notiffi</dt><dd>Plugin de notifications de Kim.</dd></div><div><dt>Switcheroo</dt><dd>Panneau de changement de personnage de Poumon (Monomer).</dd></div><div><dt>Inspiration</dt><dd>Le design s’inspire du forum <a href=\"https://ourepitaph.jcink.net/\">Our Epitaph</a> et du pen « epitaph » de pharaohleap, sur CodePen.</dd></div><div><dt>Polices et icônes</dt><dd>Playfair Display et Inter (Google Fonts, licence OFL), Obviously (Adobe Fonts), icônes Phosphor (licence MIT).</dd></div></dl>\n        </section>\n\n      </div>\n\n    </div>\n  </article>\n</div>\n\n</main>";
  mount.replaceWith(fragment.content);
})();

/* Les chapitres, sous-onglets et rubriques restent accessibles par leur adresse. */
(function () {
  function open() {
    var h = location.hash.slice(1), r = document.getElementById('lgdc-gb-' + h), c = document.getElementById('lgdc-gbc-' + h);
    var m = h.indexOf('remedes-') === 0 ? document.getElementById('lgdc-gbr-' + h.slice(8)) : null;
    var section = document.getElementById(h);
    if (c) { c.checked = true; r = document.getElementById('lgdc-gb-clans'); }
    if (m) { m.checked = true; r = document.getElementById('lgdc-gb-remedes'); }
    if (!r && section) {
      var panel = section.closest('.lgdc-gb__panel');
      if (panel) r = document.getElementById('lgdc-gb-' + panel.dataset.tab);
    }
    var sub = section ? section.closest('[data-radio]') : null;
    if (sub) document.getElementById(sub.dataset.radio).checked = true;
    if (r) r.checked = true;
    if (r && section) section.scrollIntoView();
  }
  open(); window.addEventListener('hashchange', open);
  document.querySelector('.lgdc-gb').addEventListener('change', function (e) {
    if (e.target.type !== 'radio') return;
    var id = e.target.id.replace(/^lgdc-gbc?-/, '');
    if (e.target.name === 'lgdc-gbr') id = e.target.id.replace('lgdc-gbr-', 'remedes-');
    if (e.target.name === 'lgdc-gbsy') id = e.target.id.replace('lgdc-gbsy-', 'sys-');
    if (id === 'clans') { var c = document.querySelector('[name="lgdc-gbc"]:checked'); if (c && c !== document.querySelector('[name="lgdc-gbc"]')) id = c.id.slice(9); }
    history.replaceState(null, '', '#' + id);
  });
})();
